$('#brollAnalyzeShots')?.addEventListener('click',async()=>{const file=brollSelected,button=$('#brollAnalyzeShots');if(!file)return brollStatus('ابتدا یک فایل انتخاب کن');const ffmpeg=S.settings.ffmpeg||N.defaults?.ffmpeg;if(!N.exists(ffmpeg))return brollStatus('برای تحلیل شات FFmpeg را در تنظیمات معرفی کن');button.disabled=true;$('#brollShotStatus').textContent='در حال بررسی کات‌های فایل…';try{const result=await N.spawn(ffmpeg,['-hide_banner','-nostdin','-i',file.path,'-an','-vf','scale=320:-2,select=gt(scene\\,0.38),showinfo','-f','null','-'],{timeout:180000});const cuts=[];for(const hit of String(result.stderr||'').matchAll(/pts_time:([0-9.]+)/g)){const t=Number(hit[1]);if(Number.isFinite(t)&&t>.3&&t<(file.duration||Infinity)-.2&&(cuts.length===0||t-cuts[cuts.length-1]>.4))cuts.push(t);}if(brollSelected===file){brollShotCache.set(file.path,cuts);renderBrollShots();}}catch(e){$('#brollShotStatus').textContent='تحلیل شات انجام نشد: '+e.message;}finally{button.disabled=false;}});
$('#brollPlayer')?.addEventListener('loadedmetadata',()=>{const p=$('#brollPlayer');if(brollSelected&&Number.isFinite(p.duration)){brollSelected.duration=p.duration;$('#brollOut').value=p.duration.toFixed(2);renderBrollShots();}});
$('#brollPlayer')?.addEventListener('error',()=>brollStatus('پیش‌نمایش این کدک در پنل پشتیبانی نمی‌شود؛ اگر مدت فایل خوانده شده، IN/OUT را دستی وارد کن.'));
$('#brollMarkIn')?.addEventListener('click',()=>{$('#brollIn').value=$('#brollPlayer').currentTime.toFixed(2);});
$('#brollMarkOut')?.addEventListener('click',()=>{$('#brollOut').value=$('#brollPlayer').currentTime.toFixed(2);});
$('#brollAddSegment')?.addEventListener('click',()=>{try{if(!brollSelected)throw Error('اول یک ویدیو انتخاب کن');const duration=brollSelected.duration||$('#brollPlayer').duration;if(!Number.isFinite(duration)||duration<=0)throw Error('مدت فایل خوانده نشد؛ ویدیوی پشتیبانی‌شده انتخاب کن');const x=window.VarnaBroll.segment(brollSelected.path,$('#brollIn').value,$('#brollOut').value,duration,null);x.id=Date.now()+'_'+Math.random().toString(36).slice(2,7);brollQueue.push(x);brollActiveId=x.id;saveBroll();renderBrollQueue();brollStatus('برداشت به لیست اضافه شد؛ اکنون روی تایم‌لاین زمان آن را انتخاب کن.');}catch(e){brollStatus(e.message);}});
function renderBrollQueue(){const root=$('#brollQueue');root.textContent='';brollQueue.forEach((x,i)=>{const row=document.createElement('div');row.className='broll-segment'+(x.id===brollActiveId?' active':'');row.draggable=true;row.addEventListener('dragstart',e=>e.dataTransfer?.setData('text/plain',x.id));const choose=document.createElement('button');choose.className='btn tiny secondary';choose.type='button';choose.textContent=(i+1)+'. '+x.name+' · '+(+x.start).toFixed(1)+'–'+(+x.end).toFixed(1)+'s';choose.addEventListener('click',()=>{brollActiveId=x.id;renderBrollQueue();renderBrollTimeline();});const when=document.createElement('span');when.textContent=x.at==null?'زمان: پلی‌هد':'زمان: '+(+x.at).toFixed(2)+'s';const insert=document.createElement('button');insert.className='btn tiny primary';insert.type='button';insert.textContent='درج';insert.addEventListener('click',()=>insertBrollItems([x],false));const remove=document.createElement('button');remove.className='btn tiny secondary';remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','حذف برداشت');remove.addEventListener('click',()=>{brollQueue=brollQueue.filter(y=>y.id!==x.id);if(brollActiveId===x.id)brollActiveId=brollQueue[0]?.id||null;saveBroll();renderBrollQueue();});row.append(choose,when,insert,remove);root.appendChild(row);});renderBrollTimeline();}
function renderBrollTimeline(){const root=$('#brollTimeline');root.textContent='';const info=brollTimelineInfo,duration=Number(info?.duration)||0;if(!duration){root.textContent='Composition را در After Effects فعال کن تا زمان‌بندی نمایش داده شود.';return;}const ruler=document.createElement('div');ruler.className='broll-ruler';ruler.title='زمان درج برداشت انتخابی را با کلیک تعیین کن';function placeAtPointer(e,id){const x=brollQueue.find(v=>v.id===id);if(!x)return;const rect=ruler.getBoundingClientRect();x.at=Math.max(0,Math.min(duration-(x.end-x.start),duration*(e.clientX-rect.left)/rect.width));brollActiveId=x.id;saveBroll();renderBrollQueue();}ruler.addEventListener('click',e=>placeAtPointer(e,brollActiveId));ruler.addEventListener('dragover',e=>e.preventDefault());ruler.addEventListener('drop',e=>{e.preventDefault();placeAtPointer(e,e.dataTransfer?.getData('text/plain'));});for(const m of info.markers||[]){const tick=document.createElement('span');tick.className='broll-marker';tick.style.left=Math.max(0,Math.min(100,100*m.time/duration))+'%';tick.title=m.comment||'Marker';ruler.appendChild(tick);}const head=document.createElement('i');head.className='broll-playhead';head.style.left=Math.max(0,Math.min(100,100*(info.time||0)/duration))+'%';ruler.appendChild(head);root.appendChild(ruler);for(const x of brollQueue){if(x.at==null)continue;const bar=document.createElement('button');bar.type='button';bar.className='broll-timeline-bar'+(x.id===brollActiveId?' active':'');bar.style.left=Math.max(0,100*x.at/duration)+'%';bar.style.width=Math.max(1.3,Math.min(100,100*(x.end-x.start)/duration))+'%';bar.title=x.name+' · '+x.at.toFixed(2)+'s';bar.textContent=x.name;bar.addEventListener('click',()=>{brollActiveId=x.id;renderBrollQueue();});root.appendChild(bar);}const scale=document.createElement('small');scale.textContent='۰ تا '+duration.toFixed(1)+' ثانیه · نشانگرها نارنجی، پلی‌هد آبی';root.appendChild(scale);}
async function refreshBrollTimeline(){try{brollTimelineInfo=await host('getTimelineInfo');renderBrollTimeline();}catch(e){brollTimelineInfo=null;renderBrollTimeline();brollStatus('کامپ فعال پیدا نشد: '+e.message);}}
function refreshBrollFiles(){try{brollFiles=brollFolder?window.VarnaBroll.scan(brollFolder):[];const fs=window.require('fs'),path=window.require('path');for(const f of brollExtraFiles)if(fs.existsSync(f)&&!brollFiles.some(x=>x.path===f))brollFiles.push({path:f,name:path.basename(f)});brollShown=12;renderBrollFiles();brollStatus(brollFiles.length+' ویدیو آماده است.');}catch(e){brollFiles=[];renderBrollFiles();brollStatus(e.message);}}
$('#brollChooseFolder')?.addEventListener('click',()=>{const f=B.chooseFolder('پوشهٔ ویدیوهای B-roll');if(!f)return;brollFolder=f;$('#brollFolderName').textContent=f;saveBroll();refreshBrollFiles();});
$('#brollChooseFiles')?.addEventListener('click',()=>{const files=B.chooseFiles('انتخاب چند ویدیوی B-roll',['mp4','mov','m4v','mkv','avi','webm','mpg','mpeg']);for(const f of files)if(/\.(mp4|mov|m4v|mkv|avi|webm|mpg|mpeg)$/i.test(f)&&!brollExtraFiles.includes(f))brollExtraFiles.push(f);if(files.length){saveBroll();refreshBrollFiles();}});
$('#brollRefresh')?.addEventListener('click',()=>{refreshBrollFiles();refreshBrollTimeline();});
$('#brollSearch')?.addEventListener('input',()=>{brollShown=12;renderBrollFiles();});
$('#brollMore')?.addEventListener('click',()=>{brollShown+=12;renderBrollFiles();});
async function insertBrollItems(items,sequential){if(brollBusy||!items.length)return;brollBusy=true;try{const info=await host('getTimelineInfo');let cursor=+info.time||0,done=0;for(const x of items){const at=sequential?(x.at==null?cursor:x.at):(x.at==null?cursor:x.at);brollStatus('در حال افزودن '+(done+1)+' از '+items.length+'…');const r=await host('placeBroll',{path:x.path,sourceIn:x.start,sourceOut:x.end,atTime:at,compId:info.compId,fit:$('#videoFit')?.value||'fit',audio:$('#videoKeepAudio')?.checked===true,fade:+($('#videoFade')?.value||0)});done++;cursor=at+(x.end-x.start);brollStatus(done+' برداشت وارد شد · '+r.layer);}await refreshBrollTimeline();toast(done+' برداشت روی تایم‌لاین قرار گرفت','success');}catch(e){brollStatus('درج B-roll: '+e.message);toast(e.message,'error');}finally{brollBusy=false;}}
$('#brollInsertSelected')?.addEventListener('click',async()=>{const x=brollQueue.find(y=>y.id===brollActiveId);if(!x)return brollStatus('یک برداشت را انتخاب کن');try{const t=await host('getTimelineInfo');await insertBrollItems([{...x,at:t.time}],false);}catch(e){brollStatus(e.message);}});
$('#brollInsertAll')?.addEventListener('click',()=>insertBrollItems(brollQueue,true));
$('#brollClearQueue')?.addEventListener('click',()=>{brollQueue=[];brollActiveId=null;saveBroll();renderBrollQueue();});
$$('[data-broll-edit]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{const result=await host('editSelectedVideoAtPlayhead',{mode:button.dataset.brollEdit});brollStatus('ویرایش انجام شد: '+result.action+' در '+result.time.toFixed(2)+' ثانیه');await refreshBrollTimeline();}catch(e){brollStatus('ویرایش تایم‌لاین: '+e.message);}finally{button.disabled=false;}}));
function musicAnalysisProgress(percent,message){const bar=$('#brainMusicAnalysisProgress'),label=$('#brainMusicAnalysisPercent');if(bar)bar.value=Math.max(0,Math.min(100,percent));if(label)label.textContent=String(Math.round(percent))+'٪';if(message&&$('#brainMusicStatus'))$('#brainMusicStatus').textContent=message;}
function musicSettings(){return {...(window.VarnaAudio50?.settings()||{}),endpoint:musicEndpoint,modelsFolder:$('#brainMusicModelsFolder').value.trim(),source:$('#brainMusicSource').value,business:$('#brainMusicBusiness').value,style:$('#brainMusicStyle').value,maxDuration:+$('#brainMusicDuration').value||60,note:$('#brainMusicCustomPrompt').checked?$('#brainMusicNote').value.trim():'',customPrompt:$('#brainMusicCustomPrompt').checked,editSync:$('#brainMusicEditSync').value,meter:$('#brainMusicMeter').value,vision:$('#brainMusicVision').checked,workflow:$('#brainMusicWorkflow').value,kind:$('#brainAudioKind').value,durationMode:$('#brainDurationMode').value,tempo:+$('#brainTempo').value||0,instrumentOverride:$('#brainInstrumentOverride')?.checked===true,instruments:$('#brainInstrumentOverride')?.checked===true?$('#brainInstruments').value.trim():'',exclude:$('#brainMusicExclude').value.trim(),mood:$('#brainMusicMood').value,energy:$('#brainMusicEnergy').value,rhythm:$('#brainRhythm').value};}
function renderMusicPlan(p){const box=$('#brainMusicPlan');if(!box)return;box.textContent='';if(!p){$('#brainMusicGenerate').disabled=true;return;}const summary=document.createElement('div');summary.className='director-item';const count=window.VarnaMusicEngine.segmentDurations(p.duration).length;summary.textContent='مدت '+p.duration.toFixed(1)+' ثانیه'+(count>1?' · '+count+' بخش صوتی':'')+' · '+(p.source==='manual'?'ساخت بر پایهٔ تنظیمات شما':p.cuts+' کات/مارکر مهم · '+p.events.length+' رویداد')+' · '+(p.bpm?p.bpm+' BPM':'تمپو از سبک');box.appendChild(summary);const detail=document.createElement('p');detail.className='hint';detail.textContent=window.VarnaMusicEngine.stylePrompt(p);box.appendChild(detail);$('#brainMusicGenerate').disabled=musicBusy;}
function syncMusicDurationMode(){$('#brainMusicDurationRow').hidden=$('#brainDurationMode').value!=='custom';}function syncMusicPromptMode(){$('#brainMusicNoteRow').hidden=!$('#brainMusicCustomPrompt').checked;}
function rememberMusicSettings(){const cfg=musicSettings();S.projectBrain=S.projectBrain||{};S.projectBrain.musicSettings={source:cfg.source,business:cfg.business,style:cfg.style,maxDuration:cfg.maxDuration,note:cfg.note,customPrompt:cfg.customPrompt,editSync:cfg.editSync,meter:cfg.meter,vision:cfg.vision,workflow:cfg.workflow,kind:cfg.kind,durationMode:cfg.durationMode,tempo:cfg.tempo,instrumentOverride:cfg.instrumentOverride,instruments:cfg.instruments,exclude:cfg.exclude,mood:cfg.mood,energy:cfg.energy,rhythm:cfg.rhythm};localStorage.setItem('VARNA_AUDIO_ENGINE_SETTINGS',JSON.stringify({endpoint:cfg.endpoint,modelsFolder:cfg.modelsFolder}));scheduleProjectStateSave();}
['brainMusicSource','brainMusicBusiness','brainMusicModelsFolder','brainMusicStyle','brainMusicDuration','brainMusicNote','brainMusicCustomPrompt','brainMusicEditSync','brainMusicMeter','brainMusicVision','brainMusicWorkflow','brainAudioKind','brainDurationMode','brainTempo','brainInstruments','brainInstrumentOverride','brainMusicExclude','brainMusicMood','brainMusicEnergy','brainRhythm'].forEach(id=>$('#'+id)?.addEventListener('change',()=>{if(id==='brainMusicModelsFolder')audioScan=null;rememberMusicSettings();currentMusicPlan=null;renderMusicPlan(null);if(id==='brainMusicSource')$('#brainMusicVisionRow').hidden=$('#brainMusicSource').value!=='video';if(id==='brainDurationMode')syncMusicDurationMode();if(id==='brainMusicCustomPrompt')syncMusicPromptMode();$('#brainMusicStatus').textContent='تنظیمات تغییر کرد؛ طرح را دوباره آماده کن.';if(id==='brainMusicWorkflow'||id==='brainMusicModelsFolder')refreshMusicEngineState();}));
function restoreMusicSettings(){const x=S.projectBrain?.musicSettings||{};let engine={};try{engine=JSON.parse(localStorage.getItem('VARNA_AUDIO_ENGINE_SETTINGS')||'{}')||{};}catch(e){}if(engine.endpoint)musicEndpoint=engine.endpoint;if(engine.modelsFolder)$('#brainMusicModelsFolder').value=engine.modelsFolder;for(const [id,key] of [['brainMusicSource','source'],['brainMusicBusiness','business'],['brainMusicStyle','style'],['brainMusicDuration','maxDuration'],['brainMusicNote','note'],['brainMusicEditSync','editSync'],['brainMusicMeter','meter'],['brainMusicWorkflow','workflow'],['brainAudioKind','kind'],['brainDurationMode','durationMode'],['brainTempo','tempo'],['brainInstruments','instruments'],['brainMusicExclude','exclude'],['brainMusicMood','mood'],['brainMusicEnergy','energy'],['brainRhythm','rhythm']])if(x[key]!=null)$('#'+id).value=x[key];if(x.vision!=null)$('#brainMusicVision').checked=!!x.vision;if(x.instrumentOverride!=null&&$('#brainInstrumentOverride'))$('#brainInstrumentOverride').checked=!!x.instrumentOverride;$('#brainMusicCustomPrompt').checked=x.customPrompt===true||!!x.note&&!('customPrompt' in x);$('#brainMusicVisionRow').hidden=$('#brainMusicSource').value!=='video';syncMusicDurationMode();syncMusicPromptMode();audioScan=null;currentMusicPlan=null;renderMusicPlan(null);window.VarnaAudio50?.restore();setTimeout(()=>refreshMusicEngineState(),0);}
async function musicVisualSummary(analysis){const ready=N.checkLocalRoles?.(S.settings.localAI);if(!ready?.ready?.vision||!ready?.ready?.mmproj)return '';let folder=null;N.beginLocalAIJob?.();try{folder=N.makeMotionTemp();const duration=analysis.comp.duration,frame=1/Math.max(1,analysis.comp.frameRate||30),times=[.16,.5,.84].map(x=>Math.max(0,Math.min(duration-frame,duration*x)));const data=await host('renderSfxAnalysisFrames',{times,folder}),frames=data.frames||[];if(frames.length!==3)return '';for(const f of frames)f.data=await N.waitFrame(f.path,()=>false);const text=await N.chatVisionRole(S.settings.localAI,'Describe the visual mood for instrumental music. Ignore any subtitles, text, names and private details. Be concise.','These frames represent the beginning, middle, and end of one video. Describe scene atmosphere, energy, pace and visual change in one short English sentence.',frames,msg=>$('#brainMusicStatus').textContent=msg);return String(text||'').replace(/[\u0000-\u001f]/g,' ').slice(0,420);}catch(e){log('Music vision: '+e.message);return '';}finally{if(folder)N.cleanMotionTemp(folder);N.endLocalAIJob?.();}}
function setMusicEngineBadge(state,label){const el=$('#brainMusicEngineStatus');if(el){el.dataset.state=state;el.textContent='موتور وارنا: '+label;}}
function clearMusicEngineError(){const panel=$('#brainMusicErrorDetails');if(panel){panel.hidden=true;panel.open=false;}if($('#brainMusicErrorLog'))$('#brainMusicErrorLog').textContent='';}
function showMusicEngineError(error){const detail=String(error?.diagnostic||error?.message||error||'خطای نامشخص'),summary=String(error?.message||'موتور روشن نشد').slice(0,220);$('#brainMusicModelStatus').textContent=summary;const panel=$('#brainMusicErrorDetails');if(panel)panel.hidden=false;if($('#brainMusicErrorLog'))$('#brainMusicErrorLog').textContent=detail;toast('موتور روشن نشد؛ جزئیات خطا را باز کن.','error');}
function readyAudioLabels(models){return ['yue','minimax','ace_turbo','ace_base','stable_open'].filter(k=>window.VarnaMusicEngine.completeModels(k,models?.[k])).map(k=>window.VarnaMusicEngine.WORKFLOWS[k].label);}
function scanAudioModels(force=false){const cfg=musicSettings(),found=!force&&audioScan?.folder===cfg.modelsFolder?audioScan:window.VarnaMusicEngine.discoverAudioModels(cfg.modelsFolder);audioScan=found;const names=readyAudioLabels(found.models);$('#brainMusicPathsStatus').textContent=(found.files.length?found.files.length+' فایل در '+found.folders.length+' پوشه بررسی شد. ':'')+(names.length?'مدل‌های کامل: '+names.join('، '):'مدل صوتی کامل در پوشه‌های شناخته‌شده پیدا نشد.');return found;}
let musicStatusEpoch=0;
async function refreshMusicEngineState(){const epoch=++musicStatusEpoch;try{const found=scanAudioModels(),state=await window.VarnaMusicEngine.probe(musicEndpoint);if(epoch!==musicStatusEpoch)return;if(!state.running){setMusicEngineBadge('off','خاموش');$('#brainMusicModelStatus').textContent=readyAudioLabels(found.models).length?'مدل‌ها پیدا شدند؛ موتور را روشن کن.':'مدلی آماده نیست؛ در تنظیمات پوشهٔ مدل‌ها را بررسی کن.';return;}musicEndpoint=state.base;if(!state.enabled){setMusicEngineBadge('off','خاموش در پنل');$('#brainMusicModelStatus').textContent='موتور موجود است؛ برای ساخت صدا آن را از همین بخش روشن کن.';return;}setMusicEngineBadge('running',state.owned?'روشن · تحت کنترل پنل':'روشن · مشترک');rememberMusicSettings();try{const remote=await window.VarnaMusicEngine.inventory(state.base);if(epoch!==musicStatusEpoch)return;const names=readyAudioLabels(remote),chosen=musicSettings().workflow;$('#brainMusicModelStatus').textContent=names.length?'مدل‌های آماده: '+names.join('، ')+(chosen!=='auto'&&!window.VarnaMusicEngine.completeModels(chosen,remote[chosen])?' · مدل انتخابی کامل نیست':''):'موتور روشن است اما مدل صوتی کامل در آن بارگذاری نشده است.';}catch(e){if(epoch===musicStatusEpoch)$('#brainMusicModelStatus').textContent='موتور روشن است؛ فهرست مدل‌ها خوانده نشد: '+e.message;}}catch(e){if(epoch===musicStatusEpoch){setMusicEngineBadge('off','بررسی ناموفق');$('#brainMusicModelStatus').textContent=e.message;}}}
$('#brainMusicOpenModelSettings')?.addEventListener('click',()=>{openPage('settings');setTimeout(()=>{$('#brainAudioModelSettings')?.scrollIntoView({block:'start',behavior:'smooth'});$('#brainMusicModelsFolder')?.focus();},70);});
$('#brainMusicChooseModelsFolder')?.addEventListener('click',()=>{const f=B.chooseFolder('پوشهٔ مدل‌های صدا');if(f){$('#brainMusicModelsFolder').value=f;$('#brainMusicModelsFolder').dispatchEvent(new Event('change'));}});
$('#brainMusicScanModels')?.addEventListener('click',async()=>{try{const found=scanAudioModels(true),folder=musicSettings().modelsFolder;if(folder&&Object.values(found.models).some(m=>Object.values(m).some(Boolean))){const r=window.VarnaMusicEngine.registerExternalModels({discovered:found.models},'yue');if(r.changed)$('#brainMusicPathsStatus').textContent+=' مسیرها ثبت شدند؛ اگر موتور مشترک روشن است باید از برنامهٔ مالک آن دوباره راه‌اندازی شود.';}await refreshMusicEngineState();}catch(e){$('#brainMusicPathsStatus').textContent=e.message;toast(e.message,'error');}});
$('#brainMusicEngineStart')?.addEventListener('click',async()=>{const button=$('#brainMusicEngineStart');button.disabled=true;clearMusicEngineError();setMusicEngineBadge('starting','در حال راه‌اندازی');try{const cfg=musicSettings();if(cfg.modelsFolder){const found=scanAudioModels();if(Object.values(found.models).some(m=>Object.values(m).some(Boolean)))window.VarnaMusicEngine.registerExternalModels({discovered:found.models},'yue');}const x=await window.VarnaMusicEngine.start(musicEndpoint,'',msg=>setMusicEngineBadge('starting',msg));musicEndpoint=x.base;rememberMusicSettings();await refreshMusicEngineState();}catch(e){setMusicEngineBadge('off','خطا');showMusicEngineError(e);}finally{button.disabled=false;}});
$('#brainMusicEngineStop')?.addEventListener('click',async()=>{const button=$('#brainMusicEngineStop');button.disabled=true;try{const x=await window.VarnaMusicEngine.stop();if(x.stopped){setMusicEngineBadge('off','در حال خاموش‌شدن');$('#brainMusicModelStatus').textContent='پردازش این پنل متوقف شد؛ حافظه پس از خروج موتور آزاد می‌شود.';setTimeout(()=>refreshMusicEngineState(),1200);}else{setMusicEngineBadge('off','خاموش در پنل');$('#brainMusicModelStatus').textContent='ساخت صدا در این پنل خاموش شد؛ موتور مشترک برنامهٔ دیگر روشن می‌ماند.';}}catch(e){$('#brainMusicModelStatus').textContent=e.message;toast(e.message,'error');}finally{button.disabled=false;}});
