$('#brainSyncAE')?.addEventListener('click',async()=>{
  const btn=$('#brainSyncAE');btn.disabled=true;
  try{
    const scan=await host('getVarnaCaptionLayers'),bucket=new Map(),exported=new Map(S.exportGroups().map(g=>[g.id,g]));
    for(const layer of scan.items||[]){const list=bucket.get(layer.id)||[];list.push(layer);bucket.set(layer.id,list);}
    const edits=[];let ambiguous=0;
    bucket.forEach((layers,id)=>{
      if(layers.length!==1){ambiguous++;return;}
      const layer=layers[0],group=S.group(id),old=exported.get(id);if(!group||!old)return;
      const clean=String(layer.text||'').replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069]/g,'').trim();
      const edit={id,layer,fields:[]};
      if(clean&&clean!==S.text(group))edit.fields.push('text');
      if(Math.abs(layer.start-S.groupStart(group))>.015||Math.abs(layer.end-S.groupEnd(group))>.015)edit.fields.push('timing');
      const style=S.styleFor(group),renderedSize=Number(old.style?.size)||Number(style.size)||1,ratio=renderedSize/Math.max(1,Number(style.size)||1);
      if(layer.font&&layer.font!==style.fontPS||Number(layer.size)>0&&Math.abs(layer.size-renderedSize)>.6||style.fillMode!=='gradient'&&layer.fill&&layer.fill.toUpperCase()!==String(style.fill||'#FFFFFF').toUpperCase())edit.fields.push('style');
      if(Array.isArray(layer.position)&&layer.position.length>=2){const x=layer.position[0]/scan.width*100,y=layer.position[1]/scan.height*100;if(Math.abs(x-(Number(style.x)||50))>.25||Math.abs(y-(Number(style.y)||62))>.25)edit.fields.push('position');}
      if(edit.fields.length){edit.clean=clean;edit.ratio=ratio;edits.push(edit);}
    });
    if(edits.length)S.pushUndo();
    for(const edit of edits){const group=S.group(edit.id),layer=edit.layer,locks=group.manualLocks||{};
      if(edit.fields.includes('text')){S.setText(edit.id,edit.clean);locks.text=true;}
      if(edit.fields.includes('timing')){S.setTime(edit.id,layer.start,layer.end);locks.timing=true;}
      if(edit.fields.includes('style')||edit.fields.includes('position')){const style=S.styleFor(group);
        if(edit.fields.includes('style')){if(layer.font)style.fontPS=layer.font;if(layer.size>0)style.size=layer.size/Math.max(.2,edit.ratio);if(style.fillMode!=='gradient'&&layer.fill)style.fill=layer.fill;locks.style=true;}
        if(edit.fields.includes('position')){style.x=layer.position[0]/scan.width*100;style.y=layer.position[1]/scan.height*100;locks.position=true;}
        group.styleOverride=style;
      }
      group.manualLocks=locks;group.preserve=true;
    }
    if(edits.length){S.projectBrain.plan=null;renderBrainPlan();renderAll();}
    $('#brainSyncStatus').textContent=edits.length+' کپشن از AE به‌روز شد'+(ambiguous?' · '+ambiguous+' شناسهٔ تکراری برای بررسی دستی رد شد':'')+'.';
    toast(edits.length?'تغییرات AE به پنل برگشت؛ Ctrl+Z برای بازگشت':'تغییر تازه‌ای پیدا نشد','success');
  }catch(e){toast('همگام‌سازی AE: '+e.message,'error');}finally{btn.disabled=false;}
});
