async function restoreProjectState(){projectStateReady=false;try{const info=await syncProjectContext();const result=await host('getProjectState');projectStateFile=info.file||'';projectStateLastHash='';if(result.packet){const x=N.unpackProjectState(result.packet);if(x.version!==2||!Array.isArray(x.words)||!Array.isArray(x.groups))throw Error('دادهٔ پروژه معتبر نیست');S.source=x.source||null;S.words=x.words;S.groups=x.groups;S.nextGroup=x.nextGroup||Math.max(1,...x.groups.map(g=>+g.id||0))+1;S.selectedId=S.group(x.selectedId)?x.selectedId:(S.groups[0]?.id||null);S.baselineGroups=x.baselineGroups||[];S.baselineWords=x.baselineWords||[];S.projectBrain=x.projectBrain&&typeof x.projectBrain==='object'?x.projectBrain:{brief:'',profile:'auto',plan:null};Object.assign(S.settings,x.settings||{});S.undoStack=[];S.redoStack=[];S.selectedWordIds.clear();if(info.saved&&x.correctionMemory&&N.restoreProjectCorrectionMemory?.(x.correctionMemory)){N.setMemoryScope('project');if($('#memoryScope'))$('#memoryScope').value='project';}S.saveSettings();loadControls();renderAll();renderBrainPlan();restoreMusicSettings();restoreBroll();renderCorrectionMemory();projectStateLastHash=result.packet.hash;log('وضعیت کپشن‌ها از پروژهٔ After Effects بازیابی شد.');}projectStateReady=true;}catch(e){log('Project state restore: '+e.message);toast('بازیابی دادهٔ پلاگین از پروژه ناموفق بود: '+e.message,'error');}}
async function flushProjectState(){if(B.outputBusy)return false;if(!projectStateReady||!B.available||projectSaveBusy)return false;if(!S.groups.length&&!S.words.length&&!projectStateLastHash&&!(S.projectBrain?.entityLocks||[]).length&&!(S.projectBrain?.broll?.segments||[]).length&&!(S.projectBrain?.broll?.extraFiles||[]).length&&!S.projectBrain?.broll?.folder&&!(S.settings.brands||[]).length&&!S.settings.safe.active&&!S.settings.safe.social)return true;projectSaveBusy=true;try{const packet=N.packProjectState(projectSnapshot());if(packet.hash===projectStateLastHash)return true;const info=await host('getProjectLocation');if(projectStateFile&&info.file!==projectStateFile){projectStateReady=false;log('پروژه عوض شد؛ ذخیرهٔ وضعیت قبلی متوقف شد.');return false;}await host('saveProjectState',{packet});projectStateFile=info.file||'';projectStateLastHash=packet.hash;return true;}catch(e){log('Project state save: '+e.message);return false;}finally{projectSaveBusy=false;if(projectSaveAgain){projectSaveAgain=false;scheduleProjectStateSave();}}}
function scheduleProjectStateSave(){if(!projectStateReady)return;if(projectSaveBusy){projectSaveAgain=true;return;}clearTimeout(projectSaveTimer);projectSaveTimer=setTimeout(flushProjectState,350);}
