let modelListLoaded=false,modelListLoading=false;
async function refreshModelList(force=false){
  if(modelListLoading)return;if(modelListLoaded&&!force)return;modelListLoading=true;
  const folder=$('#modelPath').value.trim();
  const list=$('#modelSelect');
  const statusEl=$('#modelStatus');
  if(!list||!window.GHAFNode?.available){ if(statusEl)statusEl.textContent='Node در دسترس نیست.'; return; }
  try{
    const models=N.listModels(folder);
    list.innerHTML='';
    const auto=document.createElement('option');
    auto.value='';auto.textContent='انتخاب خودکار بهترین مدل';
    list.appendChild(auto);
    models.forEach(m=>{
      const op=document.createElement('option');
      op.value=m.path; op.textContent=m.name; list.appendChild(op);
    });
    list.value=S.settings.modelFile||'';
    if(list.value!==S.settings.modelFile) list.value='';
    if(statusEl) statusEl.textContent=models.length?`${models.length} مدل پیدا شد.`:'هیچ فایل .bin داخل این پوشه پیدا نشد.';
  }catch(e){
    if(statusEl) statusEl.textContent='اسکن مدل‌ها ناموفق بود: '+e.message;
  }finally{modelListLoading=false;modelListLoaded=true;}
}
