async function setLivePreviewEnabled(v){
  const epoch=++previewEpoch;
  S.settings.livePreview=!!v;S.saveSettings();
  if($('#livePreview'))$('#livePreview').checked=!!v;
  if($('#livePreviewGlobal'))$('#livePreviewGlobal').checked=!!v;
  if(v){lastLivePreviewSignature='';if(B.blocked)try{await B.reconnect();}catch(e){S.settings.livePreview=false;S.saveSettings();if($('#livePreview'))$('#livePreview').checked=false;if($('#livePreviewGlobal'))$('#livePreviewGlobal').checked=false;toast('پیش‌نمایش دوباره متصل نشد: '+e.message,'error');return;}if(previewInFlight)previewAgain=true;else schedulePreview(true);return;}previewAgain=false;
  clearTimeout(previewTimer);lastLivePreviewSignature='';
  let pendingRemoval;try{
    const pending=host('removeLivePreview',{compId:previewCompId});pendingRemoval=pending;previewRemoval=pending;
    const r=await pending;
    if(epoch!==previewEpoch&&S.settings.livePreview)schedulePreview(true);
    log('Preview خاموش شد'+(r&&r.removed!=null?' — '+r.removed+' لایه Preview حذف شد':''));
  }catch(e){
    log('خطا در خاموش کردن Preview: '+e.message);
    toast('Preview کامل حذف نشد: '+e.message,'error');
  }finally{if(previewRemoval===pendingRemoval)previewRemoval=null;}
}

