// Correction provenance is stored per caption; spans are revalidated after every edit.
function correctionMarks(g){
 const value=S.text(g),marks=[];
 for(const m of g.correctionMarks||[])if(m.to&&value.slice(m.start,m.end)===m.to)marks.push(m);
 for(const e of g.memoryAppliedEdits||[])for(const m of C.diffMarks(e.from,e.to)){
   const start=e.start+m.start,end=e.start+m.end;
   if(value.slice(start,end)===m.to)marks.push({...m,start,end,ruleKey:e.ruleKey,source:'memory'});
 }
 if(!marks.length&&g.wordIds?.length){let offset=0;const seen=new Set();for(const id of g.wordIds){const w=S.word(id);if(!w)continue;const token=w.editedText!=null?w.editedText:w.text;const at=value.indexOf(token,offset);if(at<0)continue;if(w.memoryCorrected&&w.memoryOriginal&&w.memoryCorrectionId&&!seen.has(w.memoryCorrectionId)){
   seen.add(w.memoryCorrectionId);const family=g.wordIds.map(x=>S.word(x)).filter(x=>x?.memoryCorrectionId===w.memoryCorrectionId);if(S.words.filter(x=>x.memoryCorrectionId===w.memoryCorrectionId).length!==family.length){offset=at+token.length;continue;}const replacement=family.map(x=>x.editedText!=null?x.editedText:x.text).join(' ');
   const wholeAt=value.indexOf(replacement,at);if(wholeAt===at)marks.push({start:at,end:at+replacement.length,to:replacement,from:family.length===1?w.memoryOriginal:(family[0].memoryOriginalPhrase||''),ruleKey:w.memoryRuleKey,source:'transcript'});
 }offset=at+token.length;}}
 return marks.sort((a,b)=>a.start-b.start||b.end-a.end).filter((m,i,list)=>i===0||m.start>=list[i-1].end);
}
function markedHTML(g){if(!g)return '';const value=S.text(g),marks=correctionMarks(g),amb=pendingMemoryAmbiguities.filter(a=>a.groupId===g.id&&a.sourceText===value&&value.slice(a.textStart,a.textEnd)===a.wrong);const segments=marks.map((m,i)=>({start:m.start,end:m.end,kind:'corrected',index:i})).concat(amb.map((a,i)=>({start:a.textStart,end:a.textEnd,kind:'uncertain',index:i}))).sort((a,b)=>a.start-b.start||a.end-b.end);let html='',at=0;for(const s of segments){if(s.start<at||s.end>value.length||s.start>=s.end)continue;html+=esc(value.slice(at,s.start))+'<span class="'+(s.kind==='uncertain'?'uncertain-token':'corrected-token')+'" data-mark="'+s.index+'" title="'+(s.kind==='uncertain'?'نیاز به تأیید · کلیک راست برای انتخاب':'اصلاح‌شده · کلیک راست برای بازگردانی')+'">'+esc(value.slice(s.start,s.end))+'</span>';at=s.end;}return html+esc(value.slice(at));}
function renderCorrectionPreview(){const g=S.current(),el=$('#correctionTextPreview');if(el)el.innerHTML=g?markedHTML(g):'';}
function recordCorrectionMarks(g,before,after){if(!g||before===after)return;const next=C.diffMarks(before,after),pairs=correctionPairs(before,after);if(pairs.length===1)next.forEach(m=>m.ruleKey=C.phrase(pairs[0].wrong));g.correctionMarks=(g.correctionMarks||[]).filter(m=>after.slice(m.start,m.end)===m.to).concat(next);}
let correctionMenu=null;
function closeCorrectionMenu(){if(correctionMenu){correctionMenu.remove();correctionMenu=null;}}
function showCorrectionMenu(ev,g,m){const snapshot47=S.text(g);ev.preventDefault();ev.stopPropagation();closeCorrectionMenu();const menu=document.createElement('div');menu.className='correction-context-menu';menu.setAttribute('role','menu');const info=document.createElement('div');info.className='correction-context-summary';info.textContent='اصلی: '+m.from+'   ←   اصلاح: '+m.to;const restore=document.createElement('button');restore.textContent='↶ بازگرداندن همین اصلاح';restore.onclick=()=>{const current=S.group(g.id);if(!current||S.text(current)!==snapshot47){closeCorrectionMenu();toast('متن تغییر کرده؛ دوباره بررسی کن','error');return;}g=current;const value=S.text(g);if(value.slice(m.start,m.end)!==m.to){closeCorrectionMenu();return;}S.pushUndo();const next=value.slice(0,m.start)+m.from+value.slice(m.end);g.correctionExclusions=[...new Set([...(g.correctionExclusions||[]),C.phrase(m.from),...(m.ruleKey?[m.ruleKey]:[])])];const remaining=correctionMarks(g).filter(x=>x!==m&&!(x.start===m.start&&x.end===m.end)).map(x=>({...x,start:x.start>m.start?x.start+m.from.length-m.to.length:x.start,end:x.end>m.start?x.end+m.from.length-m.to.length:x.end}));g.memoryAppliedEdits=[];g.correctionMarks=remaining;S.setTextAnchored(g.id,next);closeCorrectionMenu();renderAll();schedulePreview(true);};const memory=document.createElement('button');memory.textContent='⚙ قوانین اصلاح';memory.onclick=()=>{closeCorrectionMenu();openCorrectionMemoryPanel();};const edit=document.createElement('button');edit.textContent='تغییر همین اصلاح';edit.onclick=()=>{menu.replaceChildren(info);const input=document.createElement('input');input.value=m.to;input.setAttribute('aria-label','اصلاح جدید');const save=document.createElement('button');save.textContent='تأیید تغییر';save.onclick=()=>{const right=input.value.trim();if(!right)return;try{commitReviewedCorrections([{groupId:g.id,sourceText:snapshot47,start:m.start,end:m.end,wrong:m.to,right,restoreFrom:m.from}]);learnApprovedCorrection(m.from,right);closeCorrectionMenu();}catch(e){toast(e.message,'error');}};menu.append(input,save);input.focus();};
const similar=document.createElement('button');similar.textContent='بررسی و اعمال به مشابه‌ها';similar.onclick=()=>{closeCorrectionMenu();openSimilarCorrections(g,m);};menu.append(info,restore,edit,similar,memory);document.body.appendChild(menu);correctionMenu=menu;menu.style.left=Math.max(8,Math.min(ev.clientX,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(ev.clientY,innerHeight-menu.offsetHeight-8))+'px';}
function commitReviewedCorrections(entries){
 const plans=new Map();for(const e of entries){const g=S.group(e.groupId);if(!g||S.text(g)!==e.sourceText||e.sourceText.slice(e.start,e.end)!==e.wrong)throw Error('متن تغییر کرده؛ فهرست مشابه‌ها را دوباره باز کن.');
  if(!plans.has(g.id))plans.set(g.id,{g,text:e.sourceText,edits:[],marks:correctionMarks(g)});plans.get(g.id).edits.push(e);}
 for(const plan of plans.values()){plan.edits.sort((a,b)=>a.start-b.start);for(let i=1;i<plan.edits.length;i++)if(plan.edits[i].start<plan.edits[i-1].end)throw Error('محدوده‌های انتخاب‌شده همپوشانی دارند.');}
 if(!entries.length)return 0;S.pushUndo();
 for(const plan of plans.values()){let text=plan.text;for(const e of [...plan.edits].reverse())text=text.slice(0,e.start)+e.right+text.slice(e.end);
  const retained=plan.marks.filter(m=>!plan.edits.some(e=>e.start<m.end&&e.end>m.start)).map(m=>{const delta=plan.edits.filter(e=>e.end<=m.start).reduce((v,e)=>v+e.right.length-(e.end-e.start),0);return {...m,start:m.start+delta,end:m.end+delta};});
  let delta=0;const marks=plan.edits.map(e=>{const start=e.start+delta;delta+=e.right.length-(e.end-e.start);return {start,end:start+e.right.length,from:e.restoreFrom||e.wrong,to:e.right,ruleKey:e.ruleKey||C.phrase(e.wrong),source:'review47'};});
  S.setTextAnchored(plan.g.id,text);plan.g.correctionMarks=retained.concat(marks);plan.g.memoryAppliedEdits=[];manualCorrectionBaseline.set(plan.g.id,text);
 }
 if($('#correctionLearnEnabled')?.checked!==false&&N.learnCorrectionPairs)try{N.learnCorrectionPairs(entries.map(e=>({wrong:e.restoreFrom||e.wrong,right:e.right,mode:'token',autoApply:false})));}catch(e){toast('اصلاح انجام شد؛ ذخیرهٔ حافظه ناموفق بود: '+e.message,'error');}
 applyMemoryToTranscript({undo:false});renderAll();schedulePreview(true);return entries.length;
}
function openSimilarCorrections(origin,mark){
 const rows=[];for(const g of S.groups){const sourceText=S.text(g);for(const a of C.reviewMatches(sourceText,correctionDb(),{pair:{wrong:mark.from,right:mark.to},protectedPhrases:S.projectBrain?.entityLocks||[],excluded:g.correctionExclusions||[]})){
  if(g.id===origin.id&&a.start===mark.start&&a.end===mark.end)continue;
  for(const c of a.candidates)if(C.phrase(c.right)===C.phrase(mark.to))rows.push({groupId:g.id,sourceText,start:a.start,end:a.end,wrong:a.wrong,right:c.right,reason:c.reason,ruleKey:c.ruleKey});
 }}
 document.querySelector('#correctionReview47')?.remove();const dialog=document.createElement('dialog');dialog.id='correctionReview47';dialog.className='review-dialog47';dialog.setAttribute('aria-label','بررسی مشابه‌های اصلاح');
 const title=document.createElement('h2');title.textContent='وارنا · بررسی مشابه‌ها';const list=document.createElement('div');list.className='review-matches47';const checked=[];
 for(const row of rows){const label=document.createElement('label');label.className='review-match47';const input=document.createElement('input');input.type='checkbox';input.checked=false;const copy=document.createElement('span'),b=document.createElement('b'),context=document.createElement('small');b.textContent=row.wrong+' ← '+row.right;context.textContent=row.sourceText.slice(Math.max(0,row.start-38),Math.min(row.sourceText.length,row.end+38))+' · '+({context:'تطبیق واژه و دو همسایه',word:'تطبیق خود واژه',similar:'املای نزدیک؛ نیاز به بررسی'}[row.reason]);copy.append(b,context);label.append(input,copy);list.append(label);checked.push({input,row});}
 if(!rows.length){const empty=document.createElement('p');empty.textContent='مشابه قابل‌اعمالی پیدا نشد.';list.append(empty);}
 const actions=document.createElement('div');actions.className='action-inline';const all=document.createElement('button');all.type='button';all.textContent='انتخاب همهٔ موارد فهرست';all.onclick=()=>checked.forEach(x=>x.input.checked=true);const apply=document.createElement('button');apply.type='button';apply.className='btn primary';apply.textContent='تأیید و اعمال انتخاب‌ها';const cancel=document.createElement('button');cancel.type='button';cancel.textContent='انصراف';const notice=document.createElement('p');notice.setAttribute('role','status');const trigger=document.querySelector('.caption-row[data-id="'+origin.id+'"]')||document.activeElement;
 const close=()=>{dialog.close();dialog.remove();trigger?.focus?.();};cancel.onclick=close;dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}});dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 apply.onclick=()=>{try{const entries=checked.filter(x=>x.input.checked).map(x=>x.row);if(!entries.length){notice.textContent='موردی انتخاب نشده است.';return;}const n=commitReviewedCorrections(entries);close();toast(n+' مورد با تأیید اعمال شد','success');}catch(e){notice.textContent=e.message;}};
 actions.append(all,apply,cancel);dialog.append(title,list,notice,actions);document.body.append(dialog);dialog.showModal();cancel.focus();
}
function showUncertainMenu(ev,g,a){ev.preventDefault();ev.stopPropagation();closeCorrectionMenu();const menu=document.createElement('div');menu.className='correction-context-menu';menu.setAttribute('role','menu');const info=document.createElement('div');info.className='correction-context-summary';info.textContent='نیاز به تأیید: '+a.wrong;menu.appendChild(info);for(const c of a.candidates||[]){const b=document.createElement('button');b.textContent='تأیید اصلاح: '+c.right;b.onclick=()=>{if(S.text(g)!==a.sourceText){closeCorrectionMenu();toast('متن تغییر کرده؛ دوباره بررسی کن','error');return;}S.pushUndo();const before=S.text(g);S.setTextAnchored(g.id,before.slice(0,a.textStart)+c.right+before.slice(a.textEnd));recordCorrectionMarks(g,before,S.text(g));closeCorrectionMenu();applyMemoryToTranscript({undo:false});renderAll();schedulePreview(true);};menu.appendChild(b);}const settings=document.createElement('button');settings.textContent='⚙ قوانین اصلاح';settings.onclick=()=>{closeCorrectionMenu();openCorrectionMemoryPanel();};menu.appendChild(settings);document.body.appendChild(menu);correctionMenu=menu;menu.style.left=Math.max(8,Math.min(ev.clientX,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(ev.clientY,innerHeight-menu.offsetHeight-8))+'px';}
function captionUncertain(g){return pendingMemoryAmbiguities.filter(a=>a.groupId===g.id&&a.sourceText===S.text(g)&&S.text(g).slice(a.textStart,a.textEnd)===a.wrong);}
function showCaptionCorrectionMenu(ev,g){ev.preventDefault();ev.stopPropagation();closeCorrectionMenu();const menu=document.createElement('div');menu.className='correction-context-menu';menu.setAttribute('role','menu');const label=document.createElement('div');label.className='correction-context-summary';label.textContent='اصلاحات همین متن';menu.appendChild(label);const marks=correctionMarks(g),uncertain=captionUncertain(g);for(const m of marks.slice(0,8)){const b=document.createElement('button');b.textContent='بازگردانی: '+m.to;b.onclick=()=>showCorrectionMenu(ev,g,m);menu.appendChild(b);}for(const a of uncertain.slice(0,8)){const b=document.createElement('button');b.textContent='بررسی واژهٔ نامطمئن: '+a.wrong;b.onclick=()=>showUncertainMenu(ev,g,a);menu.appendChild(b);}const settings=document.createElement('button');settings.textContent='⚙ قوانین اصلاح و استثناها';settings.onclick=()=>{closeCorrectionMenu();S.select(g.id);openCorrectionMemoryPanel();};menu.appendChild(settings);document.body.appendChild(menu);correctionMenu=menu;menu.style.left=Math.max(8,Math.min(ev.clientX,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(ev.clientY,innerHeight-menu.offsetHeight-8))+'px';}
document.addEventListener('contextmenu',e=>{const token=e.target.closest?.('.corrected-token,.uncertain-token'),row=e.target.closest?.('.caption-row'),preview=e.target.closest?.('#correctionTextPreview,#reviewText'),g=row?S.group(+row.dataset.id):preview?S.current():null;if(!g)return;if(token?.classList.contains('corrected-token')){const m=correctionMarks(g)[+token.dataset.mark];if(m)return showCorrectionMenu(e,g,m);}else if(token?.classList.contains('uncertain-token')){const a=captionUncertain(g)[+token.dataset.mark];if(a)return showUncertainMenu(e,g,a);}showCaptionCorrectionMenu(e,g);});
