function timelineDuration(){const d=+S.source?.compDuration||+S.source?.duration||0;return Math.max(1,d,...S.groups.map(g=>S.groupEnd(g)),10);}
function paintTimeTrack(a,b,max){max=Math.max(.001,+max||1);a=Math.max(0,Math.min(max,+a||0));b=Math.max(a,Math.min(max,+b||a));const left=Math.max(0,Math.min(100,a/max*100)),right=Math.max(left,Math.min(100,b/max*100));const fill=$('#timeSelectionFill');if(fill){fill.style.left=left+'%';fill.style.width=Math.max(.2,right-left)+'%';}if($('#timeStartLabel'))$('#timeStartLabel').textContent=fmt(a);if($('#timeEndLabel'))$('#timeEndLabel').textContent=fmt(b);}
