let playheadFollowTimer=null,playheadFollowBusy=false,lastFollowTime=null,followCompId=null;
function activePageName(){const n=document.querySelector('.nav-item.active');return n&&n.dataset?n.dataset.page:'';}
function playheadFollowEnabled(){return activePageName()==='text'&&$('#playheadFollowCaptions')?.checked===true&&S.groups.length>0&&!document.hidden;}
function followSuspended(){const el=document.activeElement;return B.outputBusy||document.hidden||busyFlag||motionRendering||motionDraftDirty||!!$$('.ghaf-modal').find(m=>!m.hidden)||!!(document.hasFocus?.()&&el&&(/^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName)||el.isContentEditable));}
async function syncCaptionToPlayhead(){
  if(playheadFollowBusy||!playheadFollowEnabled()||!S.groups.length||followSuspended()||!B.peekTime)return;
  playheadFollowBusy=true;
  try{
    const info=await B.peekTime();if(!info||!Number.isFinite(info.time)||followSuspended()||!playheadFollowEnabled())return;
    const expected=S.source?.compId??followCompId;if(expected!=null&&info.compId!==expected)return;
    followCompId=info.compId;
    if(lastFollowTime===info.time)return;lastFollowTime=info.time;
    const g=S.groups.find(x=>info.time>=S.groupStart(x)&&info.time<S.groupEnd(x));
    $$('.caption-row.timeline-active').forEach(row=>row.classList.remove('timeline-active'));
    if(!g)return;
    if(g.id!==S.selectedId){S.select(g.id);selectedGroups.clear();selectedGroups.add(g.id);captionSelectionAnchor=g.id;renderCaptions();renderEditor({skipPreview:true});renderMotionCaptions();invalidateMotion();}
    requestAnimationFrame(()=>{const row=$$('.caption-row').find(x=>String(x.dataset.id)===String(g.id));if(row){row.classList.add('timeline-active');row.scrollIntoView({block:'nearest',behavior:'auto'});}});
  }catch(e){}finally{playheadFollowBusy=false;}
}
function stopPlayheadFollow(){if(playheadFollowTimer){clearInterval(playheadFollowTimer);playheadFollowTimer=null;}}
function startPlayheadFollow(){stopPlayheadFollow();if(!playheadFollowEnabled())return;playheadFollowTimer=setInterval(syncCaptionToPlayhead,650);if(playheadFollowTimer&&playheadFollowTimer.unref)playheadFollowTimer.unref();}
