// A light list makes startup independent of an AE font scan.
function primeFontSelectLight(){
  const sel=$('#fontSelect');if(!sel||sel.options.length)return;
  const st=S.settings.style||{},items=[{ps:st.fontPS||'ArialMT',family:st.fontLabel||st.fontPS||'Arial'},{ps:'ArialMT',family:'Arial'},{ps:'Tahoma',family:'Tahoma'},{ps:'SegoeUI',family:'Segoe UI'}],seen={};
  for(const f of items){if(!f.ps||seen[f.ps])continue;seen[f.ps]=1;const o=document.createElement('option');o.value=f.ps;o.textContent=f.family||f.ps;o.dataset.label=f.family||f.ps;sel.appendChild(o);}
  if(st.fontPS&&seen[st.fontPS])sel.value=st.fontPS;
  const label=$('#fontStatus');if(label)label.textContent='فهرست کامل فونت‌ها هنگام ورود به بخش متن بارگذاری می‌شود.';
  syncQuickFont();
}
async function loadFonts(){
  let list=[],revision=null,err='';
  const st=$('#fontStatus');if(st)st.textContent='در حال خواندن فونت‌های After Effects…';
  try{const r=await host('listFonts');if(Array.isArray(r))list=r;else if(r&&Array.isArray(r.fonts)){list=r.fonts;revision=r.revision;}}catch(e){err=e.message;log('Font list: '+e.message);}
  if(!list.length)list=[{ps:'ArialMT',family:'Arial',style:''},{ps:'Tahoma',family:'Tahoma',style:''},{ps:'SegoeUI',family:'Segoe UI',style:''}];
  const sel=$('#fontSelect'),prev=sel.value||S.settings.style.fontPS;sel.innerHTML='';
  list.sort((a,b)=>(String(a.family)+String(a.style)).localeCompare(String(b.family)+String(b.style),'fa')).forEach(f=>{const o=document.createElement('option');o.value=f.ps;o.textContent=(f.family||f.ps)+(f.style?' — '+f.style:'');o.dataset.label=f.family||f.ps;sel.appendChild(o);});
  if([...sel.options].some(o=>o.value===prev))sel.value=prev;else if([...sel.options].some(o=>o.value===S.settings.style.fontPS))sel.value=S.settings.style.fontPS;
  if(st)st.textContent=err?('Fallback فعال — '+err):(`${list.length} فونت از After Effects خوانده شد${revision!=null?' · rev '+revision:''}`);
  syncQuickFont();if($('#cellFontPS')){const target=$('#cellFontPS');target.innerHTML='<option value="">پیش‌فرض</option>'+sel.innerHTML;target.value='';}return list;
}
