function scriptOf(t){if(/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]/.test(t))return'arabic';if(/[\u0400-\u04FF]/.test(t))return'cyrillic';if(/[A-Za-z\u00C0-\u024F]/.test(t))return'latin';if(/[\u4E00-\u9FFF\u3040-\u30FF\uAC00-\uD7AF]/.test(t))return'cjk';return'neutral';}
