function renderForeign(){const b=$('#foreignList');b.innerHTML='';foreignItems.forEach(f=>{const el=document.createElement('div');el.className='foreign-item';el.innerHTML=`<b>${esc(f.text)}</b><small>کپشن ${S.groupIndex(f.groupId)+1} — ${f.script}</small><button class="btn tiny">پیشنهاد اصلاح با AI</button>`;el.querySelector('button').addEventListener('click',()=>{S.select(f.groupId);renderAll();openPage('ai');$('#aiPreset').value='foreign';$('#aiPrompt').value=aiPrompts.foreign;runAISuggestions(true,`فقط عبارت «${f.text}» را اگر غلط است در زبان خودش اصلاح کن و باقی متن را عیناً حفظ کن.`);});b.appendChild(el);});}

