async function renderMotion(){if(B.outputBusy)return;if(motionRendering){motionGeneration++;motionPending=true;return;}const g=currentExport();if(!g){toast('اول متن انتخاب کن','error');return;}if(draftForId===g.id&&motionDraft&&motionDraftDirty){g.anim=JSON.parse(JSON.stringify(motionDraft));if((motionDraft.syncMode||'separate')!=='separate')g.bg=syncedBgForAnim(motionDraft,g.bg);}stopMotion();const generation=++motionGeneration;motionRendering=true;let session=null,folder=null;clearTimeout(previewTimer);$('#motionStatus').textContent='ساخت پیش‌نمایش متن خودت روی ویدیو…';try{let destination47=await host('checkOutput',{fallbackCompId:S.source?.compId,fallbackCompName:S.source?.comp});if(!destination47.comp)throw Error('کامپوزیشن مقصد پیش‌نمایش پیدا نشد.');if(destination47.id==null)destination47=await host('getActiveCompInfo');folder=N.makeMotionTemp();const pq=$('#motionPreviewQuality')?.value||'full',fps=pq==='fast'?4:10,maxDuration=pq==='fast'?3:8,maxSize=pq==='fast'?360:640;session=await host('beginMotionPreview',{compId:destination47.id,group:g,folder,method:$('#motionRenderMethod').value,maxDuration,maxSize});const count=Math.max(1,Math.ceil(session.duration*fps)),frames=[];for(let i=0;i<count;i++){if(generation!==motionGeneration)break;const r=await host('motionPreviewFrame',{token:session.token,index:i,time:session.start+i/fps});frames.push(await N.waitFrame(r.path,()=>generation!==motionGeneration));$('#motionStatus').textContent=`فریم ${i+1} از ${count}`;}if(generation===motionGeneration&&frames.length){motionFrames=frames;motionFrameMs=1000/fps;$('#motionScrub').max=Math.max(0,frames.length-1);$('#motionStatus').textContent=`پیش‌نمایش ${pq==='fast'?'سریع':'کامل'} · ${session.duration.toFixed(1)} ثانیه · ${fps}fps · بدون صدا`+(sceneRepairNote47([g])?' · '+sceneRepairNote47([g]):'');playMotion();}}catch(e){if(!/PREVIEW_CANCELLED/.test(e.message))$('#motionStatus').textContent='خطای پیش‌نمایش: '+e.message;}finally{if(session)try{await host('endMotionPreview',{token:session.token});}catch(e){log('پاک‌سازی Preview: '+e.message);}if(folder)N.cleanMotionTemp(folder);motionRendering=false;if(motionPending){motionPending=false;setTimeout(renderMotion,0);}}}
$('#motionRender').addEventListener('click',renderMotion);$('#motionPlay').addEventListener('click',()=>motionTimer?stopMotion():playMotion());$('#motionCancel').addEventListener('click',()=>{invalidateMotion();$('#motionStatus').textContent='لغو شد';});$('#motionScrub').addEventListener('input',e=>{stopMotion();showMotionFrame(e.target.value);});$('#motionRenderMethod').addEventListener('change',invalidateMotion);
$('#motionCaption').addEventListener('change',e=>{S.select(+e.target.value);renderAll();});$('#motionPrev').addEventListener('click',()=>$('#prevCaption').click());$('#motionNext').addEventListener('click',()=>$('#nextCaption').click());
$('#motionClear').addEventListener('click',()=>{if(!S.current())return;S.setAnim('selected',{mode:'simple',preset:'',ffx:''});renderAll();});$('#motionOutput').addEventListener('click',()=>openPage('output'));
$('#motionSave').addEventListener('click',()=>{const folder=B.chooseFolder('پوشه ذخیره پروژه GHAF');if(!folder)return;try{N.saveMotionProject(folder,{version:1,source:S.source,words:S.words,groups:S.groups,nextGroup:S.nextGroup,selectedId:S.selectedId,baselineGroups:S.baselineGroups,baselineWords:S.baselineWords,settings:{style:S.settings.style,anim:S.settings.anim,bg:S.settings.bg,layout:S.settings.layout,language:S.settings.language}});toast('پروژه ذخیره شد','success');}catch(e){toast(e.message,'error');}});
$('#motionLoad').addEventListener('click',()=>{const path=B.chooseFile('پروژه GHAF',['json']);if(!path)return;try{const x=N.loadMotionProject(path);invalidateMotion();S.source=x.source;S.words=x.words;S.groups=x.groups;S.nextGroup=Math.max(1,...x.groups.map(g=>+g.id||0))+1;S.selectedId=x.selectedId;S.baselineGroups=x.baselineGroups||[];S.baselineWords=x.baselineWords||x.words||[];Object.assign(S.settings,x.settings);S.undoStack=[];S.redoStack=[];S.selectedWordIds.clear();selectedGroups.clear();S.saveSettings();loadControls();renderAll();toast('پروژه باز شد؛ کامپ متناظر را فعال کن','success');}catch(e){toast(e.message,'error');}});


