function safePresetByKey(key){return safePresets.find(p=>p.key===key)||safePresets[0]||null;}
function safeUiPreset(){const base=safePresetByKey($('#safePresetSelect').value);if(!base)return null;const v=id=>+$('#safeMargin'+id).value;const m={left:v('Left'),right:v('Right'),top:v('Top'),bottom:v('Bottom')};const w=+$('#safeWidth').value,h=+$('#safeHeight').value;const q=window.VarnaSafe.resolve(base,{width:w,height:h,margins:m,mode:$('#safeGeometryMode')?.value||'reference'});return window.VarnaSafeCalibration?.geometry(q)||q;}
function persistSafeUi(){const preset=safeUiPreset();if(!preset)return;S.settings.safe.manual={width:preset.width,height:preset.height,margins:window.VarnaSafe.margins(preset),mode:$('#safeGeometryMode')?.value||'reference'};S.saveSettings();renderSafeMini(preset);}
function largestInnerRect(p){
  if(!p)return null;let best=null,bestArea=-1;
  (p.customPaths||[]).forEach(op=>{
    if(+op.mode!==3)return;
    (op.paths||[]).slice(1).forEach(path=>{
      const vs=path.vertices||[];if(!vs.length)return;
      const xs=vs.map(v=>+v[0]),ys=vs.map(v=>+v[1]);
      const r={x1:Math.min(...xs),y1:Math.min(...ys),x2:Math.max(...xs),y2:Math.max(...ys)};
      const a=(r.x2-r.x1)*(r.y2-r.y1);if(a>bestArea){bestArea=a;best=r;}
    });
  });return best;
}
