async function saveSafeGuidePNG(p){if(!window.require)throw Error('ذخیرهٔ راهنمای تصویری باید داخل After Effects انجام شود.');const svg=socialSVG(p,false),nr=window.require,fs=nr('fs'),path=nr('path'),os=nr('os'),crypto=nr('crypto'),folder=path.join(nr('process').env.LOCALAPPDATA||os.homedir(),'VarnaMotionStudio','Guides'),name='varna-guide-'+crypto.createHash('sha256').update(svg).digest('hex').slice(0,24)+'.png',file=path.join(folder,name);if(fs.existsSync(file)&&fs.statSync(file).size>100)return file;const canvas=document.createElement('canvas'),scale=Math.min(1,2048/Math.max(p.width,p.height));canvas.width=Math.max(1,Math.round(p.width*scale));canvas.height=Math.max(1,Math.round(p.height*scale));await new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));let done=false;const timer=setTimeout(()=>finish(Error('رندر تصویر سیف‌زون کامل نشد.')),10000);function finish(error){if(done)return;done=true;clearTimeout(timer);URL.revokeObjectURL(url);error?reject(error):resolve();}img.onload=()=>{try{canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);finish();}catch(e){finish(e);}};img.onerror=()=>finish(Error('تصویر راهنمای سیف‌زون بارگذاری نشد.'));img.src=url;});const data=canvas.toDataURL('image/png').split(',')[1];if(!data)throw Error('فایل PNG سیف‌زون ساخته نشد.');fs.mkdirSync(folder,{recursive:true});fs.writeFileSync(file,nr('buffer').Buffer.from(data,'base64'));return file;}
