function loadSafePreset(key){
  const p=safePresetByKey(key);if(!p)return;
  S.settings.safe.presetKey=p.key;S.saveSettings();
  $('#safePresetSelect').value=p.key;$('#safePresetName').textContent=p.name;
  const saved=S.settings.safe.manual,restore=saved&&S.settings.safe.manualKey===p.key;if($('#safeGeometryMode'))$('#safeGeometryMode').value=restore?saved.mode||'reference':'reference';const m=restore&&saved.mode==='manual'?saved.margins:window.VarnaSafe.margins(p);$('#safeWidth').value=restore?saved.width:p.width;$('#safeHeight').value=restore?saved.height:p.height;['Left','Right','Top','Bottom'].forEach(k=>$('#safeMargin'+k).value=m[k.toLowerCase()]);
  $('#safePresetInfo').textContent=`${p.width}×${p.height}  •  ${p.ratio}`+(p.note?'  •  '+p.note:'');
  renderSafeMini(restore?safeUiPreset():p);
  // Keep smart text grouping reasonably conservative using the largest inner safe rectangle.
  const r=window.VarnaSafe.inner(p);
  if(r&&S.source){
    S.settings.safe.left=r.x1;S.settings.safe.right=p.width-r.x2;S.settings.safe.top=r.y1;S.settings.safe.bottom=p.height-r.y2;
    S.settings.safe.width=p.width;S.settings.safe.height=p.height;
  }
}
