  safePresets.forEach(p=>{const o=document.createElement('option');o.value=p.key;o.textContent=p.name;sel.appendChild(o);});
  const wanted=S.settings.safe.presetKey||'Meta / InstagramREELS916';
  loadSafePreset(safePresetByKey(wanted)?.key||safePresets[0]?.key);
