async function runAISuggestions(selectedOnly,customInstruction){
  saveLocalAIControls();checkLocalRoles(false);
  const gs=selectedOnly?[S.current()].filter(Boolean):S.groups;
  if(!gs.length)return;
  const mode=$('#correctionMemoryMode')?.value||'auto';
  const memory=N.loadCorrectionMemory?N.loadCorrectionMemory():{items:[]};
  if(mode!=='off'&&memory.items?.length)applyMemoryToTranscript({undo:false});
  const payload=gs.map(g=>({id:g.id,text:S.text(g)}));
  const instruction=customInstruction||$('#aiPrompt').value.trim()||aiPrompts[$('#aiPreset').value]||aiPrompts.spelling;
  const memoryHint=mode!=='off'&&memory.items?.length?'\nخود واژه، همسایه‌های آن و املای نزدیک را برای پیشنهاد بررسی کن؛ تغییر فقط پس از تأیید کاربر قطعی می‌شود.': '';
  status('مدل در حال بررسی متن‌ها');
  try{
    S.pendingAI=await N.suggestCorrections(payload,{localAI:S.settings.localAI,instruction:instruction+memoryHint},{onProgress:(i,n)=>status(`اصلاح ${i} از ${n}`),onStatus:msg=>status(msg)});
    pendingIndex=S.pendingAI.length?0:-1;
    renderPending();
    toast(S.pendingAI.length?S.pendingAI.length+' پیشنهاد آماده بررسی است':'مدل تغییری پیشنهاد نکرد',S.pendingAI.length?'success':'');
    openPage('ai');
  }catch(e){toast(e.message,'error');}
  finally{status('آماده');}
}
