function renderPending(){const b=$('#pendingList');b.innerHTML='';$('#pendingCount').textContent=S.pendingAI.length+' مورد';S.pendingAI.forEach((p,i)=>{const el=document.createElement('button');el.className='pending-item'+(i===pendingIndex?' active':'');el.innerHTML=`<b>کپشن ${S.groupIndex(p.groupId)+1}</b><span>${esc(p.original)} → ${esc(p.suggestion)}</span>`;el.addEventListener('click',()=>{pendingIndex=i;renderPending();});b.appendChild(el);});const p=S.pendingAI[pendingIndex];$('#aiOriginal').value=p?.original||'';$('#aiSuggestion').value=p?.suggestion||'';}
function correctionTokenNorm(x){return String(x||'').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[ـ‌]/g,'').replace(/^[«(\[{"']+|[،؛:,.!?؟…»\)\]}"']+$/g,'').toLowerCase();}
const correctionRiskySingles=new Set(['و','یا','به','از','در','که','را','با','تا','من','تو','او','ما','این','آن','هم','یک']);
function correctionAutoSafePair(wrong,right){return C.safeAuto(wrong,right,'token');}
function correctionPairs(original,corrected){
  const a=String(original||'').trim().split(/\s+/).filter(Boolean),b=String(corrected||'').trim().split(/\s+/).filter(Boolean),pairs=[];if(!a.length||!b.length)return pairs;
  // Equal token counts are learned word-by-word. Very short/common words are retained as
  // manual-only memory so a one-off edit such as «و» -> «9» can never rewrite the transcript.
  if(a.length===b.length){
    for(let k=0;k<a.length;k++)if(correctionTokenNorm(a[k])!==correctionTokenNorm(b[k])){
      pairs.push({wrong:a[k],right:b[k],mode:'token',autoApply:false});
      if(k>0&&k<a.length-1&&correctionTokenNorm(a[k-1])===correctionTokenNorm(b[k-1])&&correctionTokenNorm(a[k+1])===correctionTokenNorm(b[k+1])){
        const wrong=[a[k-1],a[k],a[k+1]].join(' '),right=[a[k-1],b[k],a[k+1]].join(' ');
        if(!/[،؛.!?؟]$/.test(a[k-1])&&C.safeAuto(wrong,right,'context'))pairs.push({wrong,right,canonical:b[k],mode:'context',autoApply:true});
      }
    }
    return pairs;
  }
  const n=a.length,m=b.length,lcs=Array.from({length:n+1},()=>Array(m+1).fill(0));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)lcs[i][j]=correctionTokenNorm(a[i])===correctionTokenNorm(b[j])?1+lcs[i+1][j+1]:Math.max(lcs[i+1][j],lcs[i][j+1]);
  let i=0,j=0,wrong=[],right=[],lastMatchA=-1;
  const flush=(nextA)=>{
    let w=wrong.join(' ').trim(),r=right.join(' ').trim();if(!w&&!r){wrong=[];right=[];return;}
    // Insertions and one->many/many->one edits must be contextual. Use unchanged
    // neighbours as anchors instead of teaching a dangerous global replacement.
    const left=lastMatchA>=0?a[lastMatchA]:null,next=nextA<n?a[nextA]:null;
    {
      let cw=w,cr=r,anchors=0;
      if(left){cw=(left+(cw?' '+cw:''));cr=(left+(cr?' '+cr:''));anchors++;}
      if(next){cw=(cw?cw+' ':'')+next;cr=(cr?cr+' ':'')+next;anchors++;}
      if(cw&&cr&&correctionTokenNorm(cw)!==correctionTokenNorm(cr))pairs.push({wrong:cw,right:cr,mode:anchors>=2?'context':'manual',autoApply:anchors>=2&&C.safeAuto(cw,cr,'context'),canonical:r});
    }
    wrong=[];right=[];
  };
  while(i<n||j<m){if(i<n&&j<m&&correctionTokenNorm(a[i])===correctionTokenNorm(b[j])){flush(i);lastMatchA=i;i++;j++;continue;}if(j<m&&(i===n||lcs[i][j+1]>=lcs[i+1][j]))right.push(b[j++]);else if(i<n)wrong.push(a[i++]);}
  flush(i);for(const mark of C.diffMarks(original,corrected))if(mark.from&&mark.to&&!pairs.some(x=>C.phrase(x.wrong)===C.phrase(mark.from)&&C.phrase(x.right)===C.phrase(mark.to)))pairs.push({wrong:mark.from,right:mark.to,mode:'token',autoApply:false});return pairs.filter(x=>String(x.wrong).split(/\s+/).length<=10&&String(x.right).split(/\s+/).length<=12);
}
function correctionDb(){return N.effectiveCorrectionMemory?.()||N.loadCorrectionMemory?.()||{items:[]};}
function applyMemoryToTranscript(options){
 options=options||{};const db=options.db||correctionDb(),list=[];
 for(const g of S.groups){const sourceText=S.text(g);for(const a of C.reviewMatches(sourceText,db,{protectedPhrases:S.projectBrain?.entityLocks||[],excluded:g.correctionExclusions||[]}))list.push({...a,groupId:g.id,sourceText,textStart:a.start,textEnd:a.end,start:S.groupStart(g),end:S.groupEnd(g)});}
 renderMemoryAmbiguities(list);if($('#correctionMemoryLastApplied'))$('#correctionMemoryLastApplied').textContent=list.length+' مورد برای بررسی';return {hits:0,captions:0,proposals:list.length};
}
function learnApprovedCorrection(original,corrected){const pairs=correctionPairs(original,corrected);if(!pairs.length)return;const remember=$('#correctionLearnEnabled')?.checked!==false&&!!N.learnCorrectionPairs;if(remember)N.learnCorrectionPairs(pairs);if($('#correctionMemoryMode')?.value!=='off'&&$('#correctionApplyAll')?.checked!==false)applyMemoryToTranscript({undo:false,db:remember?correctionDb():C.learn({},pairs)});renderCorrectionMemory();}
let manualCorrectionSnapshot=null,manualCorrectionTimer=null,manualCorrectionBaseline=new Map();
function beginManualCorrectionLearning(){const g=S.current();if(g){S.pushUndo();manualCorrectionSnapshot={groupId:g.id,text:S.text(g)};manualCorrectionBaseline.set(g.id,S.text(g));}}
function commitManualCorrectionLearning(opts){opts=opts||{};clearTimeout(manualCorrectionTimer);const snap=manualCorrectionSnapshot;if(!snap)return 0;manualCorrectionSnapshot=null;const g=S.group(snap.groupId);if(!g)return 0;const final=S.text(g);if(final===snap.text)return 0;S.setTextAnchored(g.id,final);recordCorrectionMarks(g,snap.text,final);learnApprovedCorrection(snap.text,final);manualCorrectionBaseline.set(g.id,S.text(g));if(!opts.silent){renderAll();schedulePreview(true);}return 1;}
function scheduleAutomaticCorrectionLearning(){/* Commit on blur, change or explicit apply, never while a word is half typed. */}
function learnCurrentTranscriptCorrections(){
  if(!N.learnCorrectionPairs||!S.baselineWords?.length)return 0;const base=new Map(S.baselineWords.map(w=>[w.id,String(w.text||'')])),pairs=[];
  S.groups.filter(g=>!g.manual).forEach(g=>{const original=(g.wordIds||[]).map(id=>base.get(id)||'').filter(Boolean).join(' ').replace(/\s+/g,' ').trim(),current=S.text(g).replace(/\s+/g,' ').trim();if(original&&current&&original!==current)pairs.push(...correctionPairs(original,current));});
  const seen=new Set(),unique=pairs.filter(p=>{const k=correctionTokenNorm(p.wrong)+'→'+correctionTokenNorm(p.right);if(!k||seen.has(k))return false;seen.add(k);return true;});if(unique.length)N.learnCorrectionPairs(unique);renderCorrectionMemory();return unique.length;
}
