function renderCorrectionMemory(){const db=N.loadCorrectionMemory?.()||{items:[]},all=C.groups(db),q=C.key($('#correctionSearch')?.value||'');if($('#correctionMemoryCount'))$('#correctionMemoryCount').textContent=all.length+' واژهٔ صحیح · '+(db.items||[]).length+' شکل اشتباه';const box=$('#correctionMemoryList');if(!box)return;box.innerHTML='';const list=all.filter(g=>!q||C.key(g.right+' '+g.aliases.map(x=>x.wrong).join(' ')).includes(q));for(const g of list.slice(0,160)){const row=document.createElement('div');row.className='memory-family';const head=document.createElement('div');head.className='memory-family-head';const title=document.createElement('b');title.textContent=g.right;const edit=document.createElement('button');edit.className='btn tiny';edit.textContent='اصلاح واژهٔ نهایی';edit.onclick=()=>{const right=prompt('شکل صحیح برای همهٔ این حالت‌ها:',g.right);if(!right?.trim())return;N.replaceCorrectionCanonical?.(g.right,right.trim());if($('#correctionApplyAll')?.checked!==false)applyMemoryToTranscript();renderCorrectionMemory();renderAll();schedulePreview(true);};head.append(title,edit);row.appendChild(head);const aliases=document.createElement('div');aliases.className='memory-aliases';for(const x of g.aliases){const pill=document.createElement('button');pill.className='alias-chip';pill.textContent=x.wrong+(x.autoApply?' · تطبیق زمینه':' · تطبیق واژه')+' ×';pill.title=(x.autoApply?'این قانون در تطبیق دقیق قابل اعمال است. ':'این قانون به‌تنهایی خودکار اعمال نمی‌شود. ')+'کلیک برای حذف از حافظه';pill.onclick=()=>{N.deleteCorrectionPair?.(x.wrong,x.right);renderCorrectionMemory();};aliases.appendChild(pill);}row.appendChild(aliases);box.appendChild(row);}if(!list.length)box.textContent=q?'نتیجه‌ای پیدا نشد.':'با اولین اصلاح، حافظهٔ شخصی شما ساخته می‌شود.';scheduleProjectStateSave();}

