// Translation
let translationPendingIndex=-1;
async function ensureTranslateLocal(){saveLocalAIControls();const r=N.checkLocalRoles(S.settings.localAI);if(!r.ready.translator)throw new Error('مدل Translator در مسیر مشخص‌شده پیدا نشد.');return r.paths.translatorModel;}
function renderTranslationPending(){
  const b=$('#translatePendingList');if(!b)return;b.innerHTML='';
  $('#translatePendingCount').textContent=(S.pendingTranslation||[]).length+' مورد';
  (S.pendingTranslation||[]).forEach((p,i)=>{
    const el=document.createElement('button');el.className='pending-item'+(i===translationPendingIndex?' active':'');
    el.innerHTML=`<b>کپشن ${S.groupIndex(p.groupId)+1}</b><span>${esc(p.original)} → ${esc(p.suggestion)}</span>`;
    el.addEventListener('click',()=>{translationPendingIndex=i;renderTranslationPending();});b.appendChild(el);
  });
  const p=(S.pendingTranslation||[])[translationPendingIndex];
  $('#translateOriginal').value=p?.original||'';$('#translateSuggestion').value=p?.suggestion||'';
}
$('#btnTranslateCheckLm')?.addEventListener('click',async()=>{
  try{saveLocalAIControls();await N.prepareLocalRole('translator',S.settings.localAI,msg=>$('#translateStatus').textContent=msg);$('#translateStatus').textContent='مدل Translator آماده است.';updateLocalEngineBadge();}catch(e){$('#translateStatus').textContent='خطا: '+e.message;}
});
async function translate(selectedOnly){
  const gs=selectedOnly?[S.current()].filter(Boolean):S.groups;if(!gs.length)return;
  const items=gs.map(g=>({id:g.id,text:S.text(g)}));
  $('#translateStatus').textContent='در حال ساخت پیشنهادهای ترجمه...';
  try{
    await ensureTranslateLocal();const target=$('#translateTarget').value;S.settings.translate.target=target;S.saveSettings();
    const out=await N.translate(items,{localAI:S.settings.localAI,target},{onProgress:(i,n)=>$('#translateStatus').textContent=`ترجمه ${i} از ${n}`,onStatus:msg=>$('#translateStatus').textContent=msg});updateLocalEngineBadge();
    S.pendingTranslation=out.map(x=>({groupId:x.groupId,original:S.text(S.group(x.groupId)),suggestion:x.text}));
    translationPendingIndex=S.pendingTranslation.length?0:-1;renderTranslationPending();
    $('#translateStatus').textContent=S.pendingTranslation.length?`${S.pendingTranslation.length} ترجمه آماده بررسی است.`:'ترجمه‌ای دریافت نشد';
    toast(S.pendingTranslation.length?'ترجمه‌ها آماده تأیید هستند':'ترجمه‌ای دریافت نشد',S.pendingTranslation.length?'success':'error');
  }catch(e){$('#translateStatus').textContent='خطا: '+e.message;toast(e.message,'error');}
}
$('#btnTranslateSelected').addEventListener('click',()=>translate(true));
$('#btnTranslateAll').addEventListener('click',()=>translate(false));
$('#btnTranslateApproveOne').addEventListener('click',()=>{
  const p=S.pendingTranslation[translationPendingIndex];if(!p)return;
  if(!S.translationOriginal.has(p.groupId))S.translationOriginal.set(p.groupId,S.group(p.groupId)?.textOverride);
  S.pushUndo();S.setText(p.groupId,$('#translateSuggestion').value.trim()||p.suggestion);
  S.pendingTranslation.splice(translationPendingIndex,1);translationPendingIndex=Math.min(translationPendingIndex,S.pendingTranslation.length-1);
  renderTranslationPending();renderAll();schedulePreview(true);
});
$('#btnTranslateRejectOne').addEventListener('click',()=>{
  if(translationPendingIndex<0)return;S.pendingTranslation.splice(translationPendingIndex,1);
  translationPendingIndex=Math.min(translationPendingIndex,S.pendingTranslation.length-1);renderTranslationPending();
});
$('#btnTranslateApproveAll').addEventListener('click',()=>{
  if(!S.pendingTranslation.length)return;S.pushUndo();
  S.pendingTranslation.forEach(p=>{if(!S.translationOriginal.has(p.groupId))S.translationOriginal.set(p.groupId,S.group(p.groupId)?.textOverride);S.setText(p.groupId,p.suggestion);});
  S.pendingTranslation=[];translationPendingIndex=-1;renderTranslationPending();renderAll();schedulePreview(true);
});
$('#btnTranslateRejectAll').addEventListener('click',()=>{S.pendingTranslation=[];translationPendingIndex=-1;renderTranslationPending();});
$('#btnClearTranslation').addEventListener('click',()=>{
  S.pushUndo();for(const [id,v] of S.translationOriginal){const g=S.group(id);if(g){g.textOverride=v;g.preserve=!!v;}}
  S.translationOriginal.clear();S.pendingTranslation=[];translationPendingIndex=-1;renderTranslationPending();renderAll();schedulePreview(true);$('#translateStatus').textContent='ترجمه‌های تأییدشده به متن قبل برگشتند';
});

