function categoryForEvent(e){const str=+e.strength||0;if(e.type==='cut'){if(str<66)return 'none';return str>88?'pop':'click';}if(e.type==='scene'){return str>88?'hit':(str>72?'whoosh':'none');}if(e.type==='typography'){const p=String(e.meta?.preset||'');if(p==='typewriter')return 'typing';if(/pop|elastic|bounce|snap|swing|punch/i.test(p))return str>88?'hit':'pop';if(/glitch/i.test(p))return 'glitch';if(/focus|blur|tracking|drift|rise|slide|zoom|push|drop|spread|reveal|wipe|cascade|flow|sides|rotate/i.test(p))return str<60?'none':'whoosh';return str>78?'ui':'none';}if(e.type==='effect'){const prop=String(e.meta?.property||'').toLowerCase();if(/glitch|distort|noise|turbulent|channel|rgb/.test(prop))return 'glitch';if(/zoom|scale|position|transform|blur|wipe|transition/.test(prop))return str<58?'none':'whoosh';return str>84?'hit':(str>68?'ui':'none');}if(e.type==='textIn'){const cap=String(e.caption||'');if(/[0-9۰-۹]|کد|code/i.test(cap))return 'click';return str>84?'pop':'none';}if(e.type==='textOut')return str>72?'whoosh':'none';if(e.type==='marker')return str>82?'hit':'click';if(e.type==='motion'){const prop=String(e.meta?.property||'');if(str<58)return 'none';if(prop==='opacity')return str>72?'pop':'none';return 'whoosh';}return 'none';}
function speechAt(t,captions){return (captions||[]).some(c=>t>=+c.start-.08&&t<=+c.end+.08);}function captionAt(t,captions){const c=(captions||[]).find(c=>t>=+c.start-.15&&t<=+c.end+.15);return c?String(c.rawText||c.text||''):'';}function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
async function sfxLoudness(file){if(!file)return null;if(file.mean!=null)return file.mean;try{const r=await N.measureAudio(file.path,S.settings.ffmpeg);file.mean=r.mean;file.max=r.max;N.saveSfxCatalog(sfxCatalog);return r.mean;}catch(e){log('SFX Loudness '+file.name+': '+e.message);return null;}}
function parseJsonArray(text){const a=String(text||'').indexOf('['),b=String(text||'').lastIndexOf(']');if(a<0||b<a)throw Error('JSON array پیدا نشد');return JSON.parse(String(text).slice(a,b+1));}
async function aiPlanSfx(events,analysis){if(events.length>24){const result=new Map();for(let start=0;start<events.length;start+=24){const chunk=await aiPlanSfx(events.slice(start,start+24),analysis);if(chunk)for(const [id,value] of chunk)result.set(id+start,value);}return result.size?result:null;}if(!['hybrid','pro'].includes(S.settings.sfx.aiMode||'pro')||!events.length)return null;const compact=events.map((e,i)=>({i,time:+e.time.toFixed(3),type:e.type,strength:Math.round(e.strength),property:e.meta?.property||e.meta?.preset||'',caption:captionAt(e.time,analysis.captions).slice(0,90),reason:e.reason,visual:e.visual||null,rule:categoryForEvent(e)}));const messages=[{role:'system',content:'You are a meticulous professional sound designer. Decide whether a discrete one-shot SFX helps each event. Never use ambience/music/nature/room/city for a cut, popup or transition. Small cuts should usually be silent. Match zoom/whip motion with short whoosh, popup/UI with pop/click/UI, glitch with glitch, large impact with hit, buildup only with riser. Avoid repetitive sounds and avoid SFX on every caption. Return ONLY valid JSON array of {i,category,intensity,align,confidence,tags,why}, category one of '+JSON.stringify(SFX_EVENT_CATEGORIES)+'. Use none aggressively when silence is better.'},{role:'user',content:'Timeline/vision events:\n'+JSON.stringify(compact)}];try{const ans=await N.chatRole('type',S.settings.localAI,messages,.1,msg=>{$('#sfxAnalysisDetail').textContent=msg;});const parsed=parseJsonArray(ans),map=new Map();parsed.forEach(x=>{if(Number.isInteger(+x.i))map.set(+x.i,x);});return map;}catch(e){log('SFX local planner fallback: '+e.message);return null;}}
async function addSceneChangeEvents(analysis,forMusic){if(!forMusic&&(S.settings.sfx.aiMode||'pro')!=='pro'||!N.detectSceneChanges)return;for(const v of (analysis.videoSources||[]).slice(0,4)){try{const cuts=await N.detectSceneChanges(v.path,S.settings.ffmpeg,S.settings.sfx.sceneThreshold||.34,90),stretch=(+v.stretch||100)/100;for(const st of cuts){const ct=(+v.startTime||0)+st*stretch;if(ct>=+v.inPoint-.05&&ct<=+v.outPoint+.05)analysis.events.push({time:ct,type:'scene',strength:88,layer:v.layer,reason:'Visual scene change',meta:{sourceTime:st}});}}catch(e){log('Scene detect '+v.layer+': '+e.message);}}}
async function visionAnalyzeSfx(analysis,events){
 if((S.settings.sfx.aiMode||'pro')!=='pro'||S.settings.sfx.visualEnabled===false)return [];
 const ready=N.checkLocalRoles(S.settings.localAI);if(!ready.ready.vision||!ready.ready.mmproj){log('Vision: مدل یا mmproj آماده نیست.');return [];}
 const count=Math.max(1,Math.floor(Math.min(48,+S.settings.sfx.visionMaxFrames||21)/3)),candidates=[];
 for(const e of events.slice().sort((a,b)=>b.strength-a.strength)){if(candidates.length>=count)break;if(!candidates.some(x=>Math.abs(x.time-e.time)<.3))candidates.push(e);}
 if(!candidates.length&&S.settings.sfx.environmentSuggestions)candidates.push({time:analysis.comp.duration/2,type:'environment'});
 const out=[];let folder;try{
  folder=N.makeMotionTemp();for(const event of candidates){
   const times=[-.12,0,.12].map(d=>clamp(event.time+d,0,analysis.comp.duration-1/analysis.comp.frameRate));
   const rendered=await host('renderSfxAnalysisFrames',{times,folder}),frames=rendered.frames||[];if(frames.length!==3)continue;
   for(const frame of frames)frame.data=await N.waitFrame(frame.path,()=>false);
   const prompt='Compare before/event/after frames at seconds '+JSON.stringify(times)+'. Event: '+event.type+'. Return one JSON object with action,motion,category,intensity,shouldSound,why,environment,ambienceTags,tags. category must be whoosh,hit,pop,click,riser,glitch,ui,typing,foley,mechanical,tonal,none. Environment audio is separate. If no meaningful visual event, shouldSound=false and category=none. Captions alone should not trigger sound.';
   const answer=await N.chatVisionRole(S.settings.localAI,'Analyze this temporal triplet conservatively for sound design. Return JSON only.',prompt,frames,msg=>$('#sfxAnalysisDetail').textContent=msg);
   const a=answer.indexOf('{'),b=answer.lastIndexOf('}');if(a>=0&&b>a){const v=JSON.parse(answer.slice(a,b+1));out.push(Object.assign({},v,{time:event.time,eventType:event.type}));}
  }return out;
 }catch(e){log('Vision: '+e.message);return out;}finally{if(folder)N.cleanMotionTemp(folder);}
}
function attachVision(events,vision){if(!vision?.length)return;for(const e of events){let best=null,dist=.34;for(const v of vision){const d=Math.abs(+v.time-e.time);if(d<dist){dist=d;best=v;}}if(best)e.visual={action:best.action||'',motion:best.motion||'',impact:best.impact||'',category:best.category||'',intensity:best.intensity,tags:best.tags||'',shouldSound:best.shouldSound,why:best.why||'',environment:best.environment||'',ambienceTags:best.ambienceTags||''};}}
function musicSourceFromAnalysis(analysis){const arr=analysis.audioSources||[],rx=/music|song|beat|theme|underscore|track|موزیک|آهنگ/i;return arr.find(a=>rx.test((a.layer||'')+' '+(a.path||'')))||null;}
async function analyzeCompBeat(analysis){if(S.settings.sfx?.beatSync===false)return null;const src=musicSourceFromAnalysis(analysis);if(!src?.path)return null;try{const b=await N.analyzeBeats(src.path,S.settings.ffmpeg,{maxSec:Math.min(600,analysis.comp.duration+5)}),ratio=(+src.stretch||100)/100,start=+src.startTime||0;b.compBeats=(b.beats||[]).map(t=>start+t*ratio).filter(t=>t>=+src.inPoint-.03&&t<=+src.outPoint+.03);b.layer=src.layer;return b;}catch(e){log('Beat analysis: '+e.message);return null;}}
function maybeSnapToBeat(e,time,beat){return window.VarnaSfxPolicy.snap(Object.assign({},e,{time}),beat,S.settings.sfx.beatSync===false?'off':(S.settings.sfx.beatMode||'soft'));}
function environmentCategory(env,tags){const x=(String(env||'')+' '+String(tags||'')).toLowerCase();if(/forest|jungle|nature|tree|bird|park|garden|outdoor rural/.test(x))return 'nature';if(/city|street|traffic|urban|road|metro/.test(x))return 'city';if(/office|studio|room|interior|home|indoor|hall/.test(x))return 'room';return 'ambience';}
function buildAtmosphereSuggestions(vision,analysis){sfxAtmosphereSuggestions=[];if(S.settings.sfx?.environmentSuggestions===false||!vision?.length)return;const groups=new Map();for(const v of vision){const env=String(v.environment||'').trim(),tags=String(v.ambienceTags||'').trim();if(!env&&!tags)continue;const cat=environmentCategory(env,tags),key=cat+'|'+(env||tags);if(!groups.has(key))groups.set(key,{cat,env:env||cat,tags,count:0,time:+v.time||0});groups.get(key).count++;}const best=[...groups.values()].sort((a,b)=>b.count-a.count).slice(0,3);for(const g of best){const f=rankSfxCandidates(g.cat,g.env+' '+g.tags,'env_'+g.time,4,null,null)[0];if(!f)continue;sfxAtmosphereSuggestions.push({enabled:false,ambient:true,time:Math.max(0,g.time),eventTime:Math.max(0,g.time),align:'start',category:g.cat,path:f.path,file:f,candidates:rankSfxCandidates(g.cat,g.env+' '+g.tags,'env_'+g.time,4),db:-25,confidence:Math.min(96,58+g.count*8),reason:'محیط دیده‌شده: '+g.env,evidence:'Vision environment · '+(g.tags||g.cat),originalPath:f.path,originalCategory:g.cat});}}
function renderAtmosphereSuggestions(){const box=$('#sfxAtmosphereSuggestions');if(!box)return;box.innerHTML='';if(!sfxAtmosphereSuggestions.length){box.innerHTML='<div class="hint">پیشنهاد محیطی قابل اطمینانی پیدا نشد یا Vision خاموش است.</div>';return;}sfxAtmosphereSuggestions.forEach((x,i)=>{const row=document.createElement('div');row.className='sfx-atmo-row';row.innerHTML=`<label class="sfx-enable"><input type="checkbox" ${x.enabled?'checked':''}/></label><div><b>${esc(x.category)} · ${Math.round(x.confidence)}%</b><small>${esc(x.reason)}</small><span>${esc(x.evidence)}</span></div><select></select><button class="btn tiny">▶</button>`;const chk=row.querySelector('input'),sel=row.querySelector('select'),play=row.querySelector('button');(x.candidates||[]).forEach((f,j)=>{const o=document.createElement('option');o.value=f.path;o.textContent=(j+1)+'. '+f.name;sel.appendChild(o);});sel.value=x.path;chk.addEventListener('change',()=>{x.enabled=chk.checked;if(!x.enabled&&N.learnSfxDecision&&S.settings.sfx.learnChoices!==false){N.learnSfxDecision([{action:'reject',signature:eventSignature(x.event),category:x.category,path:x.path,eventType:x.eventType,visualContext:x.event?.visual,strength:x.event?.strength}]);x.rejectionRecorded=true;}});sel.addEventListener('change',()=>{x.path=sel.value;x.file=(x.candidates||[]).find(f=>f.path===x.path)||x.file;});let audio=null;play.addEventListener('click',()=>{if(!x.path)return;if(audio&&!audio.paused){audio.pause();play.textContent='▶';return;}audio=new Audio(N.fileURL(x.path));audio.volume=.18;audio.onended=()=>play.textContent='▶';audio.play();play.textContent='■';});box.appendChild(row);});}
function renderSfxSuggestions(){const b=$('#sfxSuggestionList');if(!b)return;b.innerHTML='';$('#sfxSuggestionCount').textContent=sfxSuggestions.length+' پیشنهاد';sfxSuggestions.forEach((x,i)=>{const row=document.createElement('div');row.className='sfx-row pro';row.innerHTML=`<label class="sfx-enable"><input type="checkbox" ${x.enabled!==false?'checked':''}/></label><b>${fmt(x.time)}</b><div class="sfx-main"><strong>${Math.round(x.confidence||70)}% · <span class="sfx-event-tag">${esc(x.eventType||'event')}</span></strong><small>${esc(x.reason)}</small><span class="sfx-analysis-evidence">${esc(x.evidence||'Timeline / Vision')}</span></div><select class="sfx-category"></select><div class="sfx-volume-wrap"><small>Gain <b class="gain-label">${Number(x.db||0).toFixed(1)} dB</b></small><input class="sfx-gain" type="range" min="-30" max="12" step="0.5" value="${Number(x.db||0)}"/><select class="sfx-choice"></select></div><button class="btn tiny sfx-play">▶</button>`;const chk=row.querySelector('.sfx-enable input'),catSel=row.querySelector('.sfx-category'),sel=row.querySelector('.sfx-choice'),play=row.querySelector('.sfx-play'),gain=row.querySelector('.sfx-gain'),gainLabel=row.querySelector('.gain-label');SFX_EVENT_CATEGORIES.filter(c=>c!=='none').forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;catSel.appendChild(o);});catSel.value=x.category||'whoosh';function refill(){const choices=rankSfxCandidates(catSel.value,[x.visualTags,x.reason,S.settings.sfx?.styleProfile].filter(Boolean).join(' '),x.time+'_'+i,+S.settings.sfx.choiceCount||8,null,x.event);x.category=catSel.value;x.candidates=choices;sel.innerHTML='';choices.forEach((f,j)=>{const o=document.createElement('option');o.value=f.path;o.textContent=(j+1)+'. '+f.name;sel.appendChild(o);});if(!choices.length){const o=document.createElement('option');o.textContent='صدای مناسب در این دسته پیدا نشد';sel.appendChild(o);x.path='';return;}if(!choices.some(c=>c.path===x.path)){x.file=choices[0];x.path=choices[0].path;}sel.value=x.path;}refill();chk.addEventListener('change',()=>{x.enabled=chk.checked;if(!x.enabled&&N.learnSfxDecision&&S.settings.sfx.learnChoices!==false){N.learnSfxDecision([{action:'reject',signature:eventSignature(x.event),category:x.category,path:x.path,eventType:x.eventType,visualContext:x.event?.visual,strength:x.event?.strength}]);x.rejectionRecorded=true;}});catSel.addEventListener('change',()=>{x.userChanged=true;refill();});sel.addEventListener('change',()=>{const f=(x.candidates||[]).find(c=>c.path===sel.value);if(f){x.userChanged=true;x.file=f;x.path=f.path;}});gain.addEventListener('input',()=>{x.db=+gain.value;gainLabel.textContent=(+gain.value).toFixed(1)+' dB';});let audio=null;play.addEventListener('click',()=>{try{if(audio&&!audio.paused){audio.pause();play.textContent='▶';return;}if(!x.path)return;audio=new Audio(N.fileURL(x.path));audio.volume=Math.max(.03,Math.min(1,Math.pow(10,(+x.db||-10)/20)));audio.onended=()=>play.textContent='▶';audio.play();play.textContent='■';}catch(e){toast('Preview صدا اجرا نشد','error');}});b.appendChild(row);});if(!sfxSuggestions.length)b.innerHTML='<div class="hint">رویداد مناسبی برای SFX پیدا نشد؛ Varna سکوت را ترجیح داد.</div>';renderAtmosphereSuggestions();}
async function analyzeSfx(){saveSfxSettings();N.beginLocalAIJob?.();if(!(sfxCatalog.items||[]).length){N.endLocalAIJob?.();toast('اول کتابخانه SFX را اسکن کن','error');return;}const state=$('#sfxAnalysisState'),detail=$('#sfxAnalysisDetail');try{state.textContent='در حال تحلیل کامپوزیشن…';detail.textContent='Timeline → Scene → Beat → Vision → Local Planner';sfxComp=await host('getActiveCompInfo');status('تحلیل Timeline');const analysis=await host('analyzeComposition',{captions:S.exportGroups()});lastSfxAnalysis=analysis;await addSceneChangeEvents(analysis);analysis.events=(analysis.events||[]).sort((a,b)=>a.time-b.time);let dialogueMean=null;if(S.settings.sfx.measureAudio&&analysis.audioSources?.length){const vals=[];for(const a of analysis.audioSources.slice(0,5)){try{const r=await N.measureAudio(a.path,S.settings.ffmpeg);if(r.mean!=null)vals.push(r.mean);}catch(e){log('Audio measure: '+e.message);}}if(vals.length)dialogueMean=vals.reduce((a,b)=>a+b,0)/vals.length;}lastBeatAnalysis=await analyzeCompBeat(analysis);const sens=+S.settings.sfx.sensitivity||56,minStrength=Math.max(18,82-sens*.68),maxCount=Math.max(1,Math.ceil(analysis.comp.duration/60*(+S.settings.sfx.maxPerMin||14))),events=(analysis.events||[]).filter(e=>e.strength>=minStrength&&sfxEventAllowed(e));events.forEach(e=>e.caption=captionAt(e.time,analysis.captions));events.splice(120);const vision=await visionAnalyzeSfx(analysis,events);attachVision(events,vision);buildAtmosphereSuggestions(vision,analysis);const planner=await aiPlanSfx(events,analysis),ranked=events.slice().sort((a,b)=>b.strength-a.strength),chosen=[];for(const e of ranked){if(chosen.length>=maxCount)break;if(chosen.some(x=>Math.abs(x.time-e.time)<(S.settings.sfx.densityLevel==='low'?.8:.35)))continue;if(e.visual&&e.visual.shouldSound===false&&e.type!=='marker')continue;let idx=events.indexOf(e),ad=planner?.get(idx),cat=ad?.category||((e.visual?.category&&SFX_EVENT_CATEGORIES.includes(e.visual.category))?e.visual.category:categoryForEvent(e));if(!SFX_EVENT_CATEGORIES.includes(cat)||cat==='none'||SFX_ATMOS_CATEGORIES.has(cat)||cat==='music')continue;if(e.type==='cut'&&['hit','riser','downer'].includes(cat))cat='click';chosen.push(Object.assign({},e,{plannedCategory:cat,aiDecision:ad}));}chosen.sort((a,b)=>a.time-b.time);const used=new Set(),out=[];for(const e of chosen){const ad=e.aiDecision||{},cat=e.plannedCategory||categoryForEvent(e),tags=[ad.tags,e.visual?.tags,e.visual?.motion,e.reason,e.caption].filter(Boolean).join(' '),f=rankSfxCandidates(cat,tags,e.time+'_'+e.layer,1,used,e)[0];if(!f)continue;used.add(f.path);let db=+S.settings.sfx.targetDb||-18;if(speechAt(e.time,analysis.captions))db-=+S.settings.sfx.duckDb||7;if(S.settings.sfx.measureAudio){const mean=await sfxLoudness(f);if(Number.isFinite(mean))db=clamp(db+((-18)-mean),-30,3);if(Number.isFinite(f.max))db=Math.min(db,-1-f.max);}const snapped=maybeSnapToBeat(e,e.time,lastBeatAnalysis);out.push({enabled:true,time:snapped.time,eventTime:snapped.time,originalEventTime:e.time,beatOffset:snapped.beatOffset,align:ad.align==='end'?'end':'start',category:cat,file:f,path:f.path,candidates:rankSfxCandidates(cat,tags,e.time+'_'+e.layer,+S.settings.sfx.choiceCount||8,used,e),db,confidence:Math.max(45,Math.min(99,+ad.confidence||(+e.visual?.intensity||e.strength))),reason:(ad.why||e.visual?.why||e.reason)+(snapped.beatOffset!=null?' · Beat snap '+(snapped.beatOffset>=0?'+':'')+snapped.beatOffset.toFixed(3)+'s':''),evidence:[e.type,e.meta?.property||e.meta?.preset||'',e.visual?.action||'',e.visual?.motion||''].filter(Boolean).join(' · '),visualTags:tags,eventType:e.type,event:e,originalPath:f.path,originalCategory:cat});}sfxSuggestions=out;renderSfxSuggestions();state.textContent=`${out.length} Cue رویدادی · ${sfxAtmosphereSuggestions.length} پیشنهاد محیطی`;detail.textContent=`Timeline ${analysis.events?.length||0} · Vision ${vision.length} · Planner ${planner?planner.size:0} · Beat ${lastBeatAnalysis?.bpm?lastBeatAnalysis.bpm+' BPM ('+lastBeatAnalysis.confidence+'%)':'ندارد'} · سکوت برای رویدادهای ضعیف حفظ شد`;toast('تحلیل Sound Design آماده شد','success');}catch(e){state.textContent='تحلیل ناموفق';detail.textContent=e.message;toast('خطای SFX: '+e.message,'error');log('SFX Analyze: '+e.stack||e.message);}finally{N.endLocalAIJob?.();status('آماده');}}
$('#btnAnalyzeSfx')?.addEventListener('click',async()=>{const b=$('#btnAnalyzeSfx');if(b.disabled)return;b.disabled=true;try{await analyzeSfx();}finally{b.disabled=false;}});
function currentSfxPlan(){return sfxSuggestions.concat(sfxAtmosphereSuggestions).filter(x=>x.enabled!==false&&x.path).map(x=>({time:x.time,eventTime:x.eventTime??x.time,align:x.align||'start',category:x.category,path:x.path,db:x.db,ambient:!!x.ambient,duration:x.duration,originalEventTime:x.originalEventTime}));}
