// R13 Audio standardization — loudness-aware gain + optional dialogue ducking
function classifyAudioRole(a){const x=((a?.layer||'')+' '+(a?.path||'')).toLowerCase();if(/^ghaf_sfx_|varna_sfx_|sfx|sound fx|whoosh|hit|impact|click|pop|glitch/.test(x)||/\\sfx\\|\/sfx\//.test(x))return 'sfx';if(/music|song|track|theme|beat|underscore|موزیک|آهنگ/.test(x))return 'music';if(/ambience|ambient|atmo|forest|jungle|city|traffic|room tone|environment|محیط/.test(x))return 'ambience';return 'dialogue';}
function roleTarget(role,a){const base=+a.targetLUFS||-16,profiles={social:[0,-10,-14,-6],dialogue:[0,-15,-18,-10],balanced:[0,-9,-13,-6],cinematic:[0,-7,-12,-4]},v=profiles[a.mixProfile||'social']||profiles.social,off={dialogue:v[0],music:v[1],ambience:v[2],sfx:v[3]};return base+(+off[role]||0);}
async function analyzeAudioMix(){
 saveSfxSettings();await syncProjectContext();const st=$('#audioMixStatus'),detail=$('#audioMixDetail');st.textContent='در حال اندازه‌گیری صدا…';
 try{const analysis=await host('analyzeComposition',{captions:S.exportGroups()}),settings=S.settings.sfx.audioStandard||audioStandardFromUI(),cache=new Map(),plan=[],warnings=[];
  for(const a of analysis.audioSources||[]){
   if(!a.path||a.timeRemap||(+a.stretch||100)<=0){warnings.push((a.layer||'Source')+' نیاز به رندر صوتی دارد');continue;}
   const ratio=(+a.stretch||100)/100,range={start:Math.max(0,(a.inPoint-a.startTime)/ratio),duration:(a.outPoint-a.inPoint)/ratio},key=a.path+'|'+range.start+'|'+range.duration;
   let m=cache.get(key);if(!m){m=await N.measureLoudness(a.path,S.settings.ffmpeg,range);cache.set(key,m);}
   if(!Number.isFinite(m.integrated)){warnings.push(a.layer+': صدای قابل اندازه‌گیری پیدا نشد');continue;}
   const role=classifyAudioRole(a),target=roleTarget(role,settings),base=Math.max(...(a.balanceBase||a.levels||[0,0]).map(Number));
   let gain=target-m.integrated-base;if(Number.isFinite(m.truePeak))gain=Math.min(gain,(+settings.truePeak)-m.truePeak-base);gain=clamp(gain,-48,18);
   plan.push({layerId:a.layerId,layerIndex:a.layerIndex,layerName:a.layer,path:a.path,role,gainDb:+gain.toFixed(2),measuredLUFS:m.integrated,truePeak:m.truePeak,targetLUFS:target,inPoint:+a.inPoint||0,outPoint:+a.outPoint||0});
  }
  const captionWindows=S.exportGroups().map(x=>({start:x.start,end:x.end}));
  const duckWindows=captionWindows.length?captionWindows:plan.filter(x=>x.role==='dialogue').map(x=>({start:x.inPoint,end:x.outPoint}));
  audioMixPlan={compId:analysis.comp.id,plan,duckWindows,truePeak:settings.truePeak,duckDb:+settings.duckDb||0,applyDucking:settings.applyDucking!==false};
  st.textContent=plan.length+' منبع صوتی تحلیل شد';detail.textContent=plan.map(x=>x.role+': '+x.measuredLUFS.toFixed(1)+' LUFS → '+x.gainDb.toFixed(1)+' dB').slice(0,8).join(' · ')+(warnings.length?' · '+warnings.join(' · '):'');return audioMixPlan;
 }catch(e){st.textContent='تحلیل صدا ناموفق';detail.textContent=e.message;throw e;}
}
