function localAIFromUI(){const x=Object.assign({},N.defaultLocalAI||{},S.settings.localAI||{});for(const [key,id] of Object.entries({root:'localRoot',runtimeDir:'localRuntimeDir',typeDir:'localTypeDir',textDir:'localTextDir',translatorDir:'localTranslatorDir',visionDir:'localVisionDir',mmproj:'localProjector',port:'localPort',...resourceFields})){const el=$('#'+id);if(el)x[key]=el.type==='number'?Number(el.value):el.value.trim();}x.releaseAfterJob=$('#resourceReleaseAfterJob')?.checked!==false;x.whisperGPU=$('#resourceWhisperGPU')?.checked!==false;return R.normalize(x,N.hardwareInfo?.().cores||8);}
function saveLocalAIControls(){const raw=localAIFromUI(),resolved=N.resolveLocalPaths?.(raw)||raw;S.settings.localAI=Object.assign(raw,{exe:resolved.exe||raw.exe,typeModel:resolved.typeModel||'',textModel:resolved.textModel||'',translatorModel:resolved.translatorModel||'',visionModel:resolved.visionModel||'',mmproj:resolved.mmproj||''});N.configureResources?.(raw);S.settings.threads=raw.threads;S.settings.vision=S.settings.vision||{};S.settings.vision.model=raw.visionModel||'';S.saveSettings();updateResourceSummary();updateLocalEngineBadge();return raw;}
function loadLocalAIControls(){const x=R.normalize(Object.assign({},N.defaultLocalAI||{},S.settings.localAI||{}),N.hardwareInfo?.().cores||8);for(const [key,id] of Object.entries({root:'localRoot',runtimeDir:'localRuntimeDir',typeDir:'localTypeDir',textDir:'localTextDir',translatorDir:'localTranslatorDir',visionDir:'localVisionDir',mmproj:'localProjector',port:'localPort',...resourceFields})){if($('#'+id))$('#'+id).value=x[key]??'';}if($('#resourceReleaseAfterJob'))$('#resourceReleaseAfterJob').checked=x.releaseAfterJob;if($('#resourceWhisperGPU'))$('#resourceWhisperGPU').checked=x.whisperGPU;N.configureResources?.(x);updateResourceSummary();updateLocalEngineBadge();}
function updateResourceSummary(){const x=localAIFromUI(),hw=N.hardwareInfo?.(),run=N.localAIStatus?.();if($('#resourceSummary'))$('#resourceSummary').textContent=x.threads+' رشته CPU · '+x.gpuLayers+' لایه GPU · Context '+x.context.toLocaleString()+' · یک پردازش هم‌زمان';if($('#hardwareSummary'))$('#hardwareSummary').textContent=hw?hw.cores+' رشتهٔ سیستم · '+hw.freeRamGB.toFixed(1)+' GB حافظه آزاد از '+hw.totalRamGB.toFixed(0)+' GB':'اطلاعات سخت‌افزار داخل پنل After Effects نمایش داده می‌شود';if($('#resourceRuntime'))$('#resourceRuntime').textContent=run?.running?'فعال · '+(run.role||'')+' · '+(run.busy||0)+' در حال اجرا · '+(run.queued||0)+' در صف':'موتور خاموش؛ در زمان نیاز بارگذاری می‌شود';}
