// AE-style shortcuts are scoped to the focused panel; input editors retain native undo/clipboard.
function editingTarget(e){const el=e.target;return !!el&&(el.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));}
let captionClipboard=null;
function selectedCaptionExports(){const ids=selectedGroups.size?[...selectedGroups]:[S.selectedId];return S.exportGroups().filter(g=>ids.includes(g.id));}
function pasteCaptions(items,plain){if(!items?.length&& !plain)return;S.pushUndo();const added=[];if(items?.length){items.forEach(x=>{const id=S.nextGroup++;S.groups.push({id,manual:true,preserve:true,wordIds:[],text:String(x.rawText||x.text||''),start:+x.start||0,end:Math.max((+x.start||0)+.04,+x.end||1),textOverride:null,styleOverride:x.style||null,animOverride:x.anim||null,bgOverride:x.bg||null});added.push(id);});}else {const id=S.nextGroup++,start=S.current()?S.groupEnd(S.current()):0;S.groups.push({id,manual:true,preserve:true,wordIds:[],text:plain,start,end:start+2});added.push(id);}S.groups.sort((a,b)=>S.groupStart(a)-S.groupStart(b));selectedGroups.clear();added.forEach(id=>selectedGroups.add(id));S.select(added[0]);renderAll();}
['copy','cut'].forEach(type=>document.addEventListener(type,e=>{if(editingTarget(e))return;const items=selectedCaptionExports();if(!items.length||!e.clipboardData)return;const plain=items.map(x=>x.rawText).join('\n');e.clipboardData.setData('text/plain',plain);try{e.clipboardData.setData('application/x-ghaf-captions+json',JSON.stringify(items));}catch(ignore){}captionClipboard={items,plain};e.preventDefault();if(type==='cut'){S.deleteGroups(items.map(x=>x.id));selectedGroups.clear();renderAll();}}));
document.addEventListener('paste',e=>{if(editingTarget(e)||!e.clipboardData)return;const plain=e.clipboardData.getData('text/plain');let items=null;try{const parsed=JSON.parse(e.clipboardData.getData('application/x-ghaf-captions+json')||'null');if(Array.isArray(parsed)&&parsed.every(x=>typeof x.text==='string'&&Number.isFinite(+x.start)&&Number.isFinite(+x.end)))items=parsed;}catch(ignore){}if(!items&&captionClipboard?.plain===plain)items=captionClipboard.items;if(items||plain){e.preventDefault();pasteCaptions(items,plain);}});
document.addEventListener('keydown',e=>{const ctrl=e.ctrlKey||e.metaKey,key=e.code||('Key'+String(e.key).toUpperCase());
  const kcode=e.keyCode||e.which||0,primary=ctrl&&e.altKey;
  if(ctrl&&!e.altKey&&!e.shiftKey&&(key==='KeyS'||kcode===83)&&projectStateReady){e.preventDefault();e.stopPropagation();clearTimeout(projectSaveTimer);(async()=>{while(projectSaveBusy)await new Promise(done=>setTimeout(done,30));const embedded=await flushProjectState(),info=await B.call('saveCurrentProject',{}, {timeout:180000});projectStateFile=info.file||projectStateFile;toast(embedded?'پروژه و دادهٔ پنل ذخیره شدند':'پروژه ذخیره شد؛ دادهٔ پنل نیاز به بررسی دارد',embedded?'success':'error');})().catch(x=>toast('ذخیرهٔ پروژه انجام نشد: '+x.message,'error'));return;}
  if(e.altKey&&!e.shiftKey){
    const actions=[openSplitPopup,openMergePopup,openQuickStyle,()=>{const r=applyMemoryToTranscript();renderAll();schedulePreview(true);toast(r.proposals+' مورد برای بررسی پیدا شد');},learnCorrectionShortcut];
    const digit=primary?({Digit1:1,Numpad1:1,Digit2:2,Numpad2:2,Digit3:3,Numpad3:3,Digit4:4,Numpad4:4,Digit5:5,Numpad5:5}[key]||({49:1,97:1,50:2,98:2,51:3,99:3,52:4,100:4,53:5,101:5}[kcode])):({KeyL:1,KeyK:2,KeyJ:3,KeyH:4,KeyG:5}[key]||({76:1,75:2,74:3,72:4,71:5}[kcode]));
    if(digit){e.preventDefault();e.stopImmediatePropagation();actions[digit-1]();return;}
  }
  if(editingTarget(e))return;
  if(ctrl&&key==='KeyZ'){e.preventDefault();if((e.shiftKey?S.redo():S.undo()))renderAll();}
  else if(ctrl&&key==='KeyA'){e.preventDefault();selectedGroups.clear();S.groups.forEach(g=>selectedGroups.add(g.id));renderCaptions();}
  else if(ctrl&&key==='KeyD'){e.preventDefault();pasteCaptions(selectedCaptionExports(),'');}
  else if(ctrl&&['KeyC','KeyX','KeyV'].includes(key)){document.execCommand({KeyC:'copy',KeyX:'cut',KeyV:'paste'}[key]);e.preventDefault();}
  else if((e.key==='Delete'||e.key==='Backspace')&&!ctrl){e.preventDefault();$('#btnDeleteCaption').click();}
},true);
function registerPanelShortcuts(){try{const interest=[];[65,67,68,83,86,88,90].forEach(keyCode=>{[false,true].forEach(shiftKey=>interest.push({keyCode,ctrlKey:true,shiftKey}));});[71,72,74,75,76].forEach(keyCode=>interest.push({keyCode,ctrlKey:false,altKey:true,shiftKey:false}));[49,50,51,52,53,97,98,99,100,101].forEach(keyCode=>interest.push({keyCode,ctrlKey:true,altKey:true,shiftKey:false}));interest.push({keyCode:75,ctrlKey:true,altKey:false,shiftKey:false});interest.push({keyCode:46});window.__adobe_cep__?.registerKeyEventsInterest(JSON.stringify(interest));}catch(e){log('ثبت میانبرهای پنل: '+e.message);}}
